INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('538916be-12e7-42d3-85ac-ca70cb1f0851', 'f56b8f6b-304b-5d50-a70c-975a0766e2a3', 'මෙම පරිසර පද්ධතියේ දිග ම ආහාර දාමයේ පෝෂී මට්ටම් හතරක් ඇත.', 'මෙම පරිසර පද්ධතියේ දිග ම ආහාර දාමයේ පෝෂී මට්ටම් හතරක් ඇත.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('43efe032-6a08-4c80-ab88-af0eae8fe47e', 'f56b8f6b-304b-5d50-a70c-975a0766e2a3', 'A මෙම පරිසර පද්ධතියේ මූලස්ථාන විශේෂයකි.', 'A මෙම පරිසර පද්ධතියේ මූලස්ථාන විශේෂයකි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d77e559a-387d-4782-bbae-b3a47530e67c', 'f56b8f6b-304b-5d50-a70c-975a0766e2a3', 'C ඉවත් කිරීම නිසා ඇටිකුකුළන්ගේ ගහනය අඩු වේ.', 'C ඉවත් කිරීම නිසා ඇටිකුකුළන්ගේ ගහනය අඩු වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('59ea06f6-e5a7-4af4-956b-17c5f0fe458e', 'f56b8f6b-304b-5d50-a70c-975a0766e2a3', 'B කටුස්සෙකු විය හැකි අතර C ගොළුබෙල්ලෙකු විය හැකි ය.', 'B කටුස්සෙකු විය හැකි අතර C ගොළුබෙල්ලෙකු විය හැකි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1d5e464a-4d9e-573f-b9e6-ee91851e9395', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 35, '<p>කෘෂිකාර්මික නිෂ්පාදනය කෙරෙහි බලපෑමක් නොදක්වන්නේ පහත සඳහන් කුමන වායු දුෂකයද?</p>', '<p>කෘෂිකාර්මික නිෂ්පාදනය කෙරෙහි බලපෑමක් නොදක්වන්නේ පහත සඳහන් කුමන වායු දුෂකයද?</p>', NULL, 'කාබන් මොනොක්සයිඩ් ($CO$) සතුන්ට සහ මිනිසුන්ට අතිශය විෂ සහිත වුවද, එය ශාක වර්ධනයට හෝ කෘෂිකාර්මික නිෂ්පාදන කෙරෙහි සෘජු ප්‍රබල බලපෑමක් එල්ල නොකරයි. $CO_2, SO_2$, ක්ලෝරෝෆ්ලුවෝරෝකාබන (CFCs) සහ නයිට්‍රජන් ඔක්සයිඩ හරිතාගාර ආචරණය, අම්ල වැසි සහ ඕසෝන් වියන ක්ෂය වීම හරහා කෘෂිකර්මාන්තයට දැඩිව බලපායි.', 'කාබන් මොනොක්සයිඩ් ($CO$) සතුන්ට සහ මිනිසුන්ට අතිශය විෂ සහිත වුවද, එය ශාක වර්ධනයට හෝ කෘෂිකාර්මික නිෂ්පාදන කෙරෙහි සෘජු ප්‍රබල බලපෑමක් එල්ල නොකරයි. $CO_2, SO_2$, ක්ලෝරෝෆ්ලුවෝරෝකාබන (CFCs) සහ නයිට්‍රජන් ඔක්සයිඩ හරිතාගාර ආචරණය, අම්ල වැසි සහ ඕසෝන් වියන ක්ෂය වීම හරහා කෘෂිකර්මාන්තයට දැඩිව බලපායි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
