INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1c3e0659-b143-4f84-8c3b-f580af0a3739', '1d5e464a-4d9e-573f-b9e6-ee91851e9395', 'නයිට්‍රජන්වල ඔක්සයිඩ', 'නයිට්‍රජන්වල ඔක්සයිඩ', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('aeacc832-2c08-5a4b-85a7-e1544a1d0391', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 36, '<p>ආහාර හෝ ආහාර ප්‍රතිපූරක හෝ ලෙස කෙළින්ම භාවිත නොකරන්නේ පහත සඳහන් කුමන ක්ෂුද්‍රජීවියාද ?</p>', '<p>ආහාර හෝ ආහාර ප්‍රතිපූරක හෝ ලෙස කෙළින්ම භාවිත නොකරන්නේ පහත සඳහන් කුමන ක්ෂුද්‍රජීවියාද ?</p>', NULL, 'Agaricus, Lentinus සහ Pleurotus යනු ආහාරයට ගන්නා හතු වර්ග වේ. Spirulina යනු ආහාර ප්‍රතිපූරකයක් (food supplement) ලෙස ගන්නා සයනොබැක්ටීරියාවකි. නමුත් Aspergillus යනු ආහාරයට නොගන්නා, බොහෝ විට ආහාර මත වැඩී විෂ ධූලක (aflatoxins) නිපදවන දිලීර ගණයකි.', 'Agaricus, Lentinus සහ Pleurotus යනු ආහාරයට ගන්නා හතු වර්ග වේ. Spirulina යනු ආහාර ප්‍රතිපූරකයක් (food supplement) ලෙස ගන්නා සයනොබැක්ටීරියාවකි. නමුත් Aspergillus යනු ආහාරයට නොගන්නා, බොහෝ විට ආහාර මත වැඩී විෂ ධූලක (aflatoxins) නිපදවන දිලීර ගණයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
