INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ed9b4731-be26-4097-9cc2-3778f56f6bdf', '34a82528-4b97-5a2e-8ae9-9c49bb7c6dc1', 'පරිවෘත්තීය සැලකූ විට ඔවුන් සියල්ලම මූලික ලෙස සමාන වේ.', 'පරිවෘත්තීය සැලකූ විට ඔවුන් සියල්ලම මූලික ලෙස සමාන වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5f9ea161-366d-4733-b4ae-677f43bc5e4f', '34a82528-4b97-5a2e-8ae9-9c49bb7c6dc1', 'තරමින් කුඩා හෙයින් ඔවුනට පරීක්ෂණාගාරවල අවශ්‍ය වන්නේ ඉතා කුඩා ඉඩකි.', 'තරමින් කුඩා හෙයින් ඔවුනට පරීක්ෂණාගාරවල අවශ්‍ය වන්නේ ඉතා කුඩා ඉඩකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4418dd46-7f93-59e1-8d49-c3e2ef27c310', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 38, '<p>පහත සඳහන් ''ප්‍රතිජීවක - නිෂේධක ක්‍රියා'' සංකලන අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>පහත සඳහන් ''ප්‍රතිජීවක - නිෂේධක ක්‍රියා'' සංකලන අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'සිප්‍රොෆ්ලොක්සසින් (Ciprofloxacin) යනු බැක්ටීරියාවල DNA ගයිරේස් එන්සයිමය නිෂේධනය කරමින් DNA සංශ්ලේෂණය වළක්වන ප්‍රතිජීවකයකි. එරිත්‍රොමයිසින් ප්‍රෝටීන සංශ්ලේෂණය ද, පෙනිසිලින් සෛල බිත්ති සංශ්ලේෂණය ද නිෂේධනය කරයි.', 'සිප්‍රොෆ්ලොක්සසින් (Ciprofloxacin) යනු බැක්ටීරියාවල DNA ගයිරේස් එන්සයිමය නිෂේධනය කරමින් DNA සංශ්ලේෂණය වළක්වන ප්‍රතිජීවකයකි. එරිත්‍රොමයිසින් ප්‍රෝටීන සංශ්ලේෂණය ද, පෙනිසිලින් සෛල බිත්ති සංශ්ලේෂණය ද නිෂේධනය කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
