INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('690991f5-4bed-4880-b74e-af3e21ce09b2', '4418dd46-7f93-59e1-8d49-c3e2ef27c310', 'පොලිමික්සින් - දිලීරවල සෛල පටල සංශ්ලේෂණය නිෂේධනය කිරීම', 'පොලිමික්සින් - දිලීරවල සෛල පටල සංශ්ලේෂණය නිෂේධනය කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4cea52d0-776a-4a16-a9b9-75ebc5414699', '4418dd46-7f93-59e1-8d49-c3e2ef27c310', 'පෙනිසිලින් - බැක්ටීරියාවල DNA සංශ්ලේෂණය නිෂේධනය කිරීම', 'පෙනිසිලින් - බැක්ටීරියාවල DNA සංශ්ලේෂණය නිෂේධනය කිරීම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8b1779d2-2600-5e2f-af1b-1d49c3f0eebb', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 39, '<p>පහත සඳහන් ඒවා අතුරෙන් ප්‍රියෝන සමග සම්බන්ධතාවක් නොදක්වන්නේ කුමක්ද?</p>', '<p>පහත සඳහන් ඒවා අතුරෙන් ප්‍රියෝන සමග සම්බන්ධතාවක් නොදක්වන්නේ කුමක්ද?</p>', NULL, 'ප්‍රියෝන (Prions) යනු න්‍යෂ්ටික අම්ල රහිත, හුදෙක් ආසාදක ප්‍රෝටීන අංශු වේ. වෛරස වලට මෙන් ලාක්ෂණික හැඩයක් ලබා දෙන සංවිධානාත්මක ප්‍රෝටීන ආවරණයක් (capsid) ප්‍රියෝන වලට නොමැත.', 'ප්‍රියෝන (Prions) යනු න්‍යෂ්ටික අම්ල රහිත, හුදෙක් ආසාදක ප්‍රෝටීන අංශු වේ. වෛරස වලට මෙන් ලාක්ෂණික හැඩයක් ලබා දෙන සංවිධානාත්මක ප්‍රෝටීන ආවරණයක් (capsid) ප්‍රියෝන වලට නොමැත.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
