INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('213d9921-3287-49fd-a379-2c2c162334a0', '8b1779d2-2600-5e2f-af1b-1d49c3f0eebb', 'න්‍යෂ්ටික අම්ල නොමැතිව ඒවාට පැවතීමට සහ බහුගුණනය වීමට පුළුවන.', 'න්‍යෂ්ටික අම්ල නොමැතිව ඒවාට පැවතීමට සහ බහුගුණනය වීමට පුළුවන.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aa21e641-d4c8-431b-8be0-41c9f2ab8aa6', '8b1779d2-2600-5e2f-af1b-1d49c3f0eebb', 'ප්‍රෝටීන ආවරණ මගින් ඒවාට ලාක්ෂණික සමමිතියක් ලබා දේ.', 'ප්‍රෝටීන ආවරණ මගින් ඒවාට ලාක්ෂණික සමමිතියක් ලබා දේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('48bad491-4378-4e1c-9905-7d07c5996acb', '8b1779d2-2600-5e2f-af1b-1d49c3f0eebb', 'ආසාදිත රුධිර පාරවිලයනය මගින් ඒවා සම්ප්‍රේෂණය වීමට පුළුවන.', 'ආසාදිත රුධිර පාරවිලයනය මගින් ඒවා සම්ප්‍රේෂණය වීමට පුළුවන.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e2f40ec5-ff88-4d11-b260-2d32d4552f1b', '8b1779d2-2600-5e2f-af1b-1d49c3f0eebb', 'ඒවායේ ප්‍රෝටීන කේතනය කරන ක්ෂීරපායී ජාන ආධාරයෙන් ඒවා බහුගුණනය වේ.', 'ඒවායේ ප්‍රෝටීන කේතනය කරන ක්ෂීරපායී ජාන ආධාරයෙන් ඒවා බහුගුණනය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1ed95899-3c22-5a09-a46d-c61a7e6996d2', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 40, '<p>ක්ෂුද්‍රජීවීන්ගේ ව්‍යාධිජනකතාව හා සම්බන්ධ නොවන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', '<p>ක්ෂුද්‍රජීවීන්ගේ ව්‍යාධිජනකතාව හා සම්බන්ධ නොවන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', NULL, 'ධාරක සෛල ආක්‍රමණය, එහි නොනැසී ජීවත්වීම, ධූලක නිපදවීම යනාදිය ව්‍යාධිජනකතාවට (pathogenicity) සෘජුව දායක වේ. නමුත් RNA පොලිමරේස් නිපදවීම යනු සියලුම ජීවීන්ගේ (ව්‍යාධිජනක නොවන ජීවීන්ගේ ද) ප්‍රෝටීන සංශ්ලේෂණයට අත්‍යවශ්‍ය සාමාන්‍ය ක්‍රියාවලියකි.', 'ධාරක සෛල ආක්‍රමණය, එහි නොනැසී ජීවත්වීම, ධූලක නිපදවීම යනාදිය ව්‍යාධිජනකතාවට (pathogenicity) සෘජුව දායක වේ. නමුත් RNA පොලිමරේස් නිපදවීම යනු සියලුම ජීවීන්ගේ (ව්‍යාධිජනක නොවන ජීවීන්ගේ ද) ප්‍රෝටීන සංශ්ලේෂණයට අත්‍යවශ්‍ය සාමාන්‍ය ක්‍රියාවලියකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
