INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('97dfa747-8029-5920-8935-df6ce541a354', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 1, '<p>To which of the following tissues does the cell type stone cells belong?</p>', '<p>To which of the following tissues does the cell type stone cells belong?</p>', NULL, 'Stone cells (sclereids) are a type of sclerenchyma tissue, which provides structural support to the plant and is composed of dead cells with heavily thickened lignified walls.', 'Stone cells (sclereids) are a type of sclerenchyma tissue, which provides structural support to the plant and is composed of dead cells with heavily thickened lignified walls.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
