INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f3b5e561-f0e2-575b-bcf8-050e3afe5b0c', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 8, '<p>Cutting a yam with a well sharpened knife is easier. The reason for this is,</p>', '<p>Cutting a yam with a well sharpened knife is easier. The reason for this is,</p>', NULL, 'A sharpened knife has a much smaller surface area at its cutting edge. Since $Pressure = \frac{Force}{Area}$, a smaller contact area results in a significantly greater pressure for the same amount of applied force, allowing it to easily cut through the yam.', 'A sharpened knife has a much smaller surface area at its cutting edge. Since $Pressure = \frac{Force}{Area}$, a smaller contact area results in a significantly greater pressure for the same amount of applied force, allowing it to easily cut through the yam.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
