INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6a254fb9-5cde-5ce7-bdd6-f43ac55109a0', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 9, '<p>The formula of the compound formed by the element X with oxygen is XO while the formula of the compound formed by the element Y with sodium is NaY.<br><br>What is the formula of the compound formed by the combination of X and Y?</p>', '<p>The formula of the compound formed by the element X with oxygen is XO while the formula of the compound formed by the element Y with sodium is NaY.<br><br>What is the formula of the compound formed by the combination of X and Y?</p>', NULL, 'In the compound $XO$, Oxygen always has a valency of 2, which means element $X$ must also have a valency of 2 (i.e., $X^{2+}$). In the compound $NaY$, Sodium always has a valency of 1, so element $Y$ must have a valency of 1 (i.e., $Y^{-}$). When $X$ and $Y$ combine, cross-multiplying their valencies results in the formula $XY_{2}$.', 'In the compound $XO$, Oxygen always has a valency of 2, which means element $X$ must also have a valency of 2 (i.e., $X^{2+}$). In the compound $NaY$, Sodium always has a valency of 1, so element $Y$ must have a valency of 1 (i.e., $Y^{-}$). When $X$ and $Y$ combine, cross-multiplying their valencies results in the formula $XY_{2}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option