INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1fac066f-ce7a-5028-ba61-a8f723ca2127', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 12, '<p>Which of the following is the false statement about the resistance of a metallic conductor?</p>', '<p>Which of the following is the false statement about the resistance of a metallic conductor?</p>', NULL, 'The resistance of a metallic conductor is a physical property defined by $R = \rho \frac{l}{A}$. It depends on the material''s resistivity ($\rho$), length ($l$), cross-sectional area ($A$), and temperature. It does not depend on the potential difference applied across it, as stated by Ohm''s Law where $R$ is the constant of proportionality.', 'The resistance of a metallic conductor is a physical property defined by $R = \rho \frac{l}{A}$. It depends on the material''s resistivity ($\rho$), length ($l$), cross-sectional area ($A$), and temperature. It does not depend on the potential difference applied across it, as stated by Ohm''s Law where $R$ is the constant of proportionality.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
