INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f29f0fcd-5532-46b3-8f91-256230613d1f', '1fac066f-ce7a-5028-ba61-a8f723ca2127', 'It is directly proportional to the length.', 'It is directly proportional to the length.', NULL, 'sanitized', 'v1', 1, 0);
