INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9a8e1b41-2a43-541e-9a38-a37adaed82d0', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 13, '<p>Which of the following is the correct way of positioning the delivery tubes to collect two samples of the gases carbon dioxide and hydrogen into gas jars?</p>', '<p>Which of the following is the correct way of positioning the delivery tubes to collect two samples of the gases carbon dioxide and hydrogen into gas jars?</p>', NULL, 'Carbon dioxide ($CO_2$) is denser than air, so it sinks. It must be collected by downward delivery (into an upright gas jar), displacing the air upwards. Hydrogen ($H_2$) is less dense than air, so it rises. It must be collected by upward delivery (into an inverted gas jar), displacing the air downwards.', 'Carbon dioxide ($CO_2$) is denser than air, so it sinks. It must be collected by downward delivery (into an upright gas jar), displacing the air upwards. Hydrogen ($H_2$) is less dense than air, so it rises. It must be collected by upward delivery (into an inverted gas jar), displacing the air downwards.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
