INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2c207af8-f989-590d-b9f3-ed4f5c2a6780', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 14, '<p>Which of the following is not a property of synthetic linear polymers?</p>', '<p>Which of the following is not a property of synthetic linear polymers?</p>', NULL, 'Synthetic linear polymers (like most common plastics) are generally non-biodegradable because microorganisms lack the enzymes required to easily break down their long, artificially bonded molecular chains.', 'Synthetic linear polymers (like most common plastics) are generally non-biodegradable because microorganisms lack the enzymes required to easily break down their long, artificially bonded molecular chains.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
