INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9d64afb5-318b-5775-99b9-d7ae6a61ac37', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 16, '<p>Which chamber of the human heart has the thickest walls?</p>', '<p>Which chamber of the human heart has the thickest walls?</p>', NULL, 'The left ventricle has the thickest muscular walls because it is responsible for forcefully pumping oxygenated blood through the aorta against the high resistance of the entire systemic circulation.', 'The left ventricle has the thickest muscular walls because it is responsible for forcefully pumping oxygenated blood through the aorta against the high resistance of the entire systemic circulation.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
