INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a5ca40ea-dffe-50d3-bc4f-c4e0fc5f2a48', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 19, '<p>Which of the following statement is true about the image formed by a plane mirror?</p>', '<p>Which of the following statement is true about the image formed by a plane mirror?</p>', NULL, 'An image formed by a plane mirror is always virtual, erect, equal in size to the object, situated at the same distance behind the mirror as the object is in front of it, and is laterally inverted (left appears as right).', 'An image formed by a plane mirror is always virtual, erect, equal in size to the object, situated at the same distance behind the mirror as the object is in front of it, and is laterally inverted (left appears as right).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('28827f3f-5728-401b-9a1a-ce20f08cf1a1', 'a5ca40ea-dffe-50d3-bc4f-c4e0fc5f2a48', 'The image is formed on the side of the object itself.', 'The image is formed on the side of the object itself.', NULL, 'sanitized', 'v1', 0, 1);
