INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2ef78e06-6a34-54fe-b3ff-bfdafb03d9f1', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 21, '<p>When a small amount of Benedict solution is added to a certain food extract and heated, no colour change occurred.<br>When a little of dilute sulphuric acid is added to it and heated, the solution turned orange. The nutrient contained in this food extract would be,</p>', '<p>When a small amount of Benedict solution is added to a certain food extract and heated, no colour change occurred.<br>When a little of dilute sulphuric acid is added to it and heated, the solution turned orange. The nutrient contained in this food extract would be,</p>', NULL, 'Sucrose is a non-reducing sugar, meaning it will not initially react with Benedict''s solution to cause a color change. Boiling it with dilute sulfuric acid hydrolyzes the sucrose into glucose and fructose, which are reducing sugars. These monosaccharides then react with Benedict''s reagent to produce the orange/brick-red precipitate.', 'Sucrose is a non-reducing sugar, meaning it will not initially react with Benedict''s solution to cause a color change. Boiling it with dilute sulfuric acid hydrolyzes the sucrose into glucose and fructose, which are reducing sugars. These monosaccharides then react with Benedict''s reagent to produce the orange/brick-red precipitate.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, san