INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7ebf9d6c-d265-5612-8c9d-64ccb3fc919c', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 22, '<p>Consider the following characteristics possessed by a living species.<br>A - An organized nucleus is absent.<br>B - can be destroyed by antibiotics<br>C - can be either pathogenic or autotrophic<br><br>Of these, the characteristics owned by the organisms belonging to domain bacteria are,</p>', '<p>Consider the following characteristics possessed by a living species.<br>A - An organized nucleus is absent.<br>B - can be destroyed by antibiotics<br>C - can be either pathogenic or autotrophic<br><br>Of these, the characteristics owned by the organisms belonging to domain bacteria are,</p>', NULL, 'Bacteria are prokaryotes, meaning they lack an organized membrane-bound nucleus (A). They can be targeted and destroyed by antibiotics (B). Furthermore, bacteria have highly diverse metabolic strategies, encompassing both pathogenic (disease-causing) and autotrophic (photosynthetic/chemosynthetic) forms (C). Therefore, all three statements are correct.', 'Bacteria are prokaryotes, meaning they lack an organized membrane-bound nucleus (A). They can be targeted and destroyed by antibiotics (B). Furthermore, bacteria have highly diverse metabolic strategies, encompassing both pathogenic (disease-causing) and autotrophic (photosynthetic/chemosynthetic) forms (C). Therefore, all three statements are correct.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
