INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ed8e5f7e-2c36-5bd6-8df4-4b29e1394906', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 26, '<p>Of the two solutions A and B, no colour change occurred when a few drops of phenolphthalein was added to solution A. When equal volumes of solutions of A and B of equal concentration were mixed and allowed to react, an aqueous solution of C was obtained and its pH was 7. The solutions A, B and C respectively could be,</p>', '<p>Of the two solutions A and B, no colour change occurred when a few drops of phenolphthalein was added to solution A. When equal volumes of solutions of A and B of equal concentration were mixed and allowed to react, an aqueous solution of C was obtained and its pH was 7. The solutions A, B and C respectively could be,</p>', NULL, 'Phenolphthalein remains colourless in acidic and neutral environments but turns pink in basic ones. Because A caused no colour change, it must be an acid (e.g., $HCl$). When reacted with an equal volume and concentration of B, it forms a perfectly neutral solution C (pH = 7), implying B is a strong base (e.g., $NaOH$) and C is a neutral salt ($NaCl$).', 'Phenolphthalein remains colourless in acidic and neutral environments but turns pink in basic ones. Because A caused no colour change, it must be an acid (e.g., $HCl$). When reacted with an equal volume and concentration of B, it forms a perfectly neutral solution C (pH = 7), implying B is a strong base (e.g., $NaOH$) and C is a neutral salt ($NaCl$).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
