INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('44ae7e54-6aef-55b9-90d6-05dd8a224e61', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 27, '<p>The carbohydrate products first formed during photosynthesis, stored temporarily in chloroplasts and translocated through the phloem respectively are,</p>', '<p>The carbohydrate products first formed during photosynthesis, stored temporarily in chloroplasts and translocated through the phloem respectively are,</p>', NULL, 'During photosynthesis, plants initially produce simple monosaccharides (like glucose). If produced in excess, it is polymerized and stored temporarily as a polysaccharide (starch) within the chloroplasts. For translocation to other parts of the plant via the phloem, it is converted into a non-reducing disaccharide (sucrose).', 'During photosynthesis, plants initially produce simple monosaccharides (like glucose). If produced in excess, it is polymerized and stored temporarily as a polysaccharide (starch) within the chloroplasts. For translocation to other parts of the plant via the phloem, it is converted into a non-reducing disaccharide (sucrose).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
