INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ed3c1e7a-1fd4-5564-9a72-80f1d0f1f49f', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 29, '<p>The number of autosomes and the sex chromosome that can be present in a human ovum respectively are,</p>', '<p>The number of autosomes and the sex chromosome that can be present in a human ovum respectively are,</p>', NULL, 'A typical human somatic cell contains 46 chromosomes (44 autosomes and 2 sex chromosomes). Gametes (ova and sperm) undergo meiosis and are haploid, containing precisely half that number. A human ovum will carry 22 autosomes and always carries a single X sex chromosome.', 'A typical human somatic cell contains 46 chromosomes (44 autosomes and 2 sex chromosomes). Gametes (ova and sperm) undergo meiosis and are haploid, containing precisely half that number. A human ovum will carry 22 autosomes and always carries a single X sex chromosome.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
