INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('eafcbd90-13ab-50e3-9973-a6f3dd84bd51', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 31, '<p>The power of an electric heater is 1 000 W. The amount of electrical energy spent when this heater operated for a period of 2 hours was,</p>', '<p>The power of an electric heater is 1 000 W. The amount of electrical energy spent when this heater operated for a period of 2 hours was,</p>', NULL, 'First, convert power to kilowatts: $1000 \text{ W} = 1 \text{ kW}$. Electrical energy is calculated as $Energy = Power \times Time$. Thus, $1 \text{ kW} \times 2 \text{ hours} = 2 \text{ kWh}$.', 'First, convert power to kilowatts: $1000 \text{ W} = 1 \text{ kW}$. Electrical energy is calculated as $Energy = Power \times Time$. Thus, $1 \text{ kW} \times 2 \text{ hours} = 2 \text{ kWh}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
