INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f9d34c6c-30c3-5632-8117-ca6861c01401', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 32, '<p>Which of the following metals can be used for cathodic protection of iron?</p>', '<p>Which of the following metals can be used for cathodic protection of iron?</p>', NULL, 'Cathodic protection (often achieved via a sacrificial anode) requires a metal that is more reactive than iron, so that it oxidizes preferentially. In the electrochemical reactivity series, Zinc ($Zn$) is situated above iron, whereas Silver ($Ag$), Copper ($Cu$), and Tin ($Sn$) are below it.', 'Cathodic protection (often achieved via a sacrificial anode) requires a metal that is more reactive than iron, so that it oxidizes preferentially. In the electrochemical reactivity series, Zinc ($Zn$) is situated above iron, whereas Silver ($Ag$), Copper ($Cu$), and Tin ($Sn$) are below it.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
