INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5c7c7cba-4df2-58b0-887f-b2c41ae2f775', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 33, '<p>The force exerted vertically upwards on a rocket of mass $m$ due to combustion of fuel is $R$. If $g$ is the acceleration due to gravity, the acceleration with which the rocket moves is,</p>', '<p>The force exerted vertically upwards on a rocket of mass $m$ due to combustion of fuel is $R$. If $g$ is the acceleration due to gravity, the acceleration with which the rocket moves is,</p>', NULL, 'By Newton''s Second Law ($F_{net} = ma$), the net vertical force acting on the rocket is the upward thrust ($R$) minus the downward force of its weight ($mg$). Therefore, $R - mg = ma$. Rearranging for acceleration ($a$) yields $a = \frac{R - mg}{m}$.', 'By Newton''s Second Law ($F_{net} = ma$), the net vertical force acting on the rocket is the upward thrust ($R$) minus the downward force of its weight ($mg$). Therefore, $R - mg = ma$. Rearranging for acceleration ($a$) yields $a = \frac{R - mg}{m}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
