INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c7649877-6745-5f1a-88f3-a1309af5e99f', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 36, '<p>The boiling points of hydrogen chloride and water are $-85^{\circ}C$ and $100^{\circ}C$ respectively. Which of the following statements explains the cause for this difference?</p>', '<p>The boiling points of hydrogen chloride and water are $-85^{\circ}C$ and $100^{\circ}C$ respectively. Which of the following statements explains the cause for this difference?</p>', NULL, 'Boiling points are determined by the strength of intermolecular forces, not intramolecular covalent bonds. Water molecules exhibit extensive and strong hydrogen bonding between each other. Hydrogen chloride ($HCl$) is a polar molecule, but it only possesses weaker dipole-dipole interactions. These weaker forces in $HCl$ require much less thermal energy to break, resulting in a significantly lower boiling point.', 'Boiling points are determined by the strength of intermolecular forces, not intramolecular covalent bonds. Water molecules exhibit extensive and strong hydrogen bonding between each other. Hydrogen chloride ($HCl$) is a polar molecule, but it only possesses weaker dipole-dipole interactions. These weaker forces in $HCl$ require much less thermal energy to break, resulting in a significantly lower boiling point.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d053cca7-50b2-4933-be0b-e3f947141a7c', 'c7649877-6745-5f1a-88f3-a1309af5e99f', 'The intermolecular forces among hydrogen chloride molecules are weaker than the intermolecular forces among water molecules.', 'The intermolecular forces among hydrogen chloride molecules are weaker than the intermolecular forces among water molecules.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('02e46afb-20a4-4372-a97e-8a52a74bddb0', 'c7649877-6745-5f1a-88f3-a1309af5e99f', 'The relative molecular mass of hydrogen chloride is greater than the relative molecular mass of water.', 'The relative molecular mass of hydrogen chloride is greater than the relative molecular mass of water.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('96919f95-3803-4232-9225-0b1819225bc3', 'c7649877-6745-5f1a-88f3-a1309af5e99f', 'The covalent bonds among the atoms are stronger in water than those in hydrogen chloride.', 'The covalent bonds among the atoms are stronger in water than those in hydrogen chloride.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8e0baa18-f2fa-4ac8-aeb7-382874af4692', 'c7649877-6745-5f1a-88f3-a1309af5e99f', 'Water molecules are polar whereas hydrogen chloride molecules are non-polar.', 'Water molecules are polar whereas hydrogen chloride molecules are non-polar.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('efd6cf4e-9432-510f-babc-b4330ac9b314', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 37, '<p>A sheet of zinc suspended on a spring balance is immersed in a hydrochloride acid solution bringing them to react. Some time after the beginning of the reaction another quantity of the acid solution was added into the reaction mixture. If the spring balance reading ($m$) was plotted against time ($t$), which of the following graphs is most likely to be obtained?</p>', '<p>A sheet of zinc suspended on a spring balance is immersed in a hydrochloride acid solution bringing them to react. Some time after the beginning of the reaction another quantity of the acid solution was added into the reaction mixture. If the spring balance reading ($m$) was plotted against time ($t$), which of the following graphs is most likely to be obtained?</p>', NULL, 'The spring balance registers apparent weight ($Weight - Upthrust$). As the zinc reacts and dissolves, its mass and volume decrease, slowly lowering the balance reading. Once the acid is completely consumed, the reaction stops and the curve plateaus. Instantaneously pouring more liquid (acid) increases the depth of the solution, which suddenly increases the buoyant upthrust on the system. This registers as an instantaneous vertical drop in apparent weight on the graph. The reaction then resumes, and the curve continues sloping downward.', 'The spring balance registers apparent weight ($Weight - Upthrust$). As the zinc reacts and dissolves, its mass and volume decrease, slowly lowering the balance reading. Once the acid is completely consumed, the reaction stops and the curve plateaus. Instantaneously pouring more liquid (acid) increases the depth of the solution, which suddenly increases the buoyant upthrust on the system. This registers as an instantaneous vertical drop in apparent weight on the graph. The reaction then resumes, and the curve continues sloping downward.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
