INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e068bd89-b2ef-5984-8f80-9fbbc9ca1b03', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 38, '<p>Of the following, which one is the false statement?</p>', '<p>Of the following, which one is the false statement?</p>', NULL, 'Acid rain is predominantly caused by the atmospheric release of sulfur dioxide ($SO_2$) and oxides of nitrogen ($NO_x$), not chlorofluorocarbons. Chlorofluorocarbons (CFCs) are specifically known for causing ozone layer depletion.', 'Acid rain is predominantly caused by the atmospheric release of sulfur dioxide ($SO_2$) and oxides of nitrogen ($NO_x$), not chlorofluorocarbons. Chlorofluorocarbons (CFCs) are specifically known for causing ozone layer depletion.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
