INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('48f6ee84-352d-5423-a9b1-95d7953c41fb', 'b2637861-9fe4-517c-9e66-c7da63bf6136', 40, '<p>In a traditional tank (wewa), what is the structure that prevents the erosion of the tank bund?</p>', '<p>In a traditional tank (wewa), what is the structure that prevents the erosion of the tank bund?</p>', NULL, 'The ''ralapanawa'' is a traditional Sri Lankan structural feature in irrigation tanks. It consists of a layer of stone pitching laid on the inner slope of the earthen tank bund. It is specifically engineered to break the force of water waves and ripples, protecting the earth from continuous erosion.', 'The ''ralapanawa'' is a traditional Sri Lankan structural feature in irrigation tanks. It consists of a layer of stone pitching laid on the inner slope of the earthen tank bund. It is specifically engineered to break the force of water waves and ripples, protecting the earth from continuous erosion.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
