INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3811fc4f-84d5-5137-b529-5de761194abe', 'b6abf530-2b43-546c-af2e-342932e49ee9', 8, '<p>ASCII කේතයේ A අනුලක්ෂණය $65_{10}$ මගින් නිරූපණය කෙරේ. එම කේතයේ $01000011_2$ මගින් නිරූපණය වන්නේ කුමන අනුලක්ෂණයද?</p>', '<p>ASCII කේතයේ A අනුලක්ෂණය $65_{10}$ මගින් නිරූපණය කෙරේ. එම කේතයේ $01000011_2$ මගින් නිරූපණය වන්නේ කුමන අනුලක්ෂණයද?</p>', NULL, '$01000011_2$ හි දශම අගය ගණනය කිරීම: $64 + 2 + 1 = 67_{10}$.<br>A = 65, B = 66, C = 67 වේ. එබැවින් අනුලක්ෂණය ''C'' වේ.', '$01000011_2$ හි දශම අගය ගණනය කිරීම: $64 + 2 + 1 = 67_{10}$.<br>A = 65, B = 66, C = 67 වේ. එබැවින් අනුලක්ෂණය ''C'' වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
