INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('55943719-3e4e-5725-9654-79209adb364c', 'b6abf530-2b43-546c-af2e-342932e49ee9', 9, '<p>මෙහෙයුම් පද්ධතියක කාර්යයක් නොවන්නේ පහත කවරක්ද?</p>', '<p>මෙහෙයුම් පද්ධතියක කාර්යයක් නොවන්නේ පහත කවරක්ද?</p>', NULL, 'ලේඛනයක පාඨ එකෙල්ල කිරීම (Alignment) යනු යෙදුම් මෘදුකාංගයක (උදා: MS Word හි) කාර්යයකි. ක්‍රියායන (Process), මතක (Memory) සහ ගොනු (File) කළමනාකරණය මෙහෙයුම් පද්ධතියේ ප්‍රධාන කාර්යයන් වේ.', 'ලේඛනයක පාඨ එකෙල්ල කිරීම (Alignment) යනු යෙදුම් මෘදුකාංගයක (උදා: MS Word හි) කාර්යයකි. ක්‍රියායන (Process), මතක (Memory) සහ ගොනු (File) කළමනාකරණය මෙහෙයුම් පද්ධතියේ ප්‍රධාන කාර්යයන් වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('eac0deba-c868-4771-a199-2a9d0d3ac1dc', '55943719-3e4e-5725-9654-79209adb364c', 'එක් එක් පරිශීලක ක්‍රියායනයට (process) සකසනයේ ධාවනය වීමට අවස්ථාව ලබාදීම', 'එක් එක් පරිශීලක ක්‍රියායනයට (process) සකසනයේ ධාවනය වීමට අවස්ථාව ලබාදීම', NULL, 'sanitized', 'v1', 0, 1);
