INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2cf62d52-432f-5f13-b844-1bc7cec97ad4', 'b6abf530-2b43-546c-af2e-342932e49ee9', 16, '<p>වැඩපතක B2:D4 පරාසයට කෝෂ කීයක් අයත් වේද?</p>', '<p>වැඩපතක B2:D4 පරාසයට කෝෂ කීයක් අයත් වේද?</p>', NULL, 'B, C, D යන තීරු 3ක් සහ 2, 3, 4 යන පේළි 3ක් ඇත. මුළු කෝෂ ගණන = $3 \times 3 = 9$ වේ. (B2, B3, B4, C2, C3, C4, D2, D3, D4).', 'B, C, D යන තීරු 3ක් සහ 2, 3, 4 යන පේළි 3ක් ඇත. මුළු කෝෂ ගණන = $3 \times 3 = 9$ වේ. (B2, B3, B4, C2, C3, C4, D2, D3, D4).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
