INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3a378157-97b5-4905-9a9a-a57eaec5e686', '8b88d796-0c70-5d89-b3fe-b4a6050e76af', 'කිසිදු පරීක්ෂා කිරීමක් (testing) අවශ්‍ය නොවීම', 'කිසිදු පරීක්ෂා කිරීමක් (testing) අවශ්‍ය නොවීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('33f97c8b-16c1-5037-9668-f0477b1531b4', 'b6abf530-2b43-546c-af2e-342932e49ee9', 35, '<p>ප්‍රතිග්‍රහණ පරීක්ෂාව (acceptance testing) පහත කවරක හොඳින්ම විස්තර කෙරේ ද?</p>', '<p>ප්‍රතිග්‍රහණ පරීක්ෂාව (acceptance testing) පහත කවරක හොඳින්ම විස්තර කෙරේ ද?</p>', NULL, 'ප්‍රතිග්‍රහණ පරීක්ෂාව (Acceptance testing) යනු පද්ධතිය ගොඩනැගීම අවසන් වූ පසු, එය සේවාදායකයාගේ හෝ පරිශීලකයාගේ මූලික අවශ්‍යතාවයන් නිවැරදිව සපුරාලන්නේද යන්න තහවුරු කරගැනීම සඳහා පරිශීලකයන් විසින්ම සිදු කරන අවසන් පරීක්ෂාවයි.', 'ප්‍රතිග්‍රහණ පරීක්ෂාව (Acceptance testing) යනු පද්ධතිය ගොඩනැගීම අවසන් වූ පසු, එය සේවාදායකයාගේ හෝ පරිශීලකයාගේ මූලික අවශ්‍යතාවයන් නිවැරදිව සපුරාලන්නේද යන්න තහවුරු කරගැනීම සඳහා පරිශීලකයන් විසින්ම සිදු කරන අවසන් පරීක්ෂාවයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b39d674f-1514-48f9-827e-187d37a11db8', '33f97c8b-16c1-5037-9668-f0477b1531b4', 'පරිශීලක අවශ්‍යතා පිළිගත හැකිදැයි පිරික්සීමට එය ක්‍රමලේඛකයන් (programmers) විසින් සිදු කෙරේ.', 'පරිශීලක අවශ්‍යතා පිළිගත හැකිදැයි පිරික්සීමට එය ක්‍රමලේඛකයන් (programmers) විසින් සිදු කෙරේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ecc195ac-dcaa-4c42-bc19-adcd829b2f8e', '33f97c8b-16c1-5037-9668-f0477b1531b4', 'එය ක්‍රමලේඛකයන් විසින් කේතන දෝෂ පරීක්ෂා කිරීමට සිදු කෙරේ.', 'එය ක්‍රමලේඛකයන් විසින් කේතන දෝෂ පරීක්ෂා කිරීමට සිදු කෙරේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e0c46a15-0ae6-456e-9ae7-fdd51fba6960', '33f97c8b-16c1-5037-9668-f0477b1531b4', 'පද්ධතිය තම අවශ්‍යතා සපුරන්නේ දැයි පරීක්ෂා කිරීමට එය පරිශීලකයන් විසින් සිදු කෙරේ.', 'පද්ධතිය තම අවශ්‍යතා සපුරන්නේ දැයි පරීක්ෂා කිරීමට එය පරිශීලකයන් විසින් සිදු කෙරේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4a5e90af-dd6c-47a5-8403-e91774a5105a', '33f97c8b-16c1-5037-9668-f0477b1531b4', 'පද්ධතිය පිහිටුවීමෙන් (deployment) පසුව නව විශේෂාංග එකතු කිරීමට එය පරිශීලකයන් විසින් සිදු කෙරේ.', 'පද්ධතිය පිහිටුවීමෙන් (deployment) පසුව නව විශේෂාංග එකතු කිරීමට එය පරිශීලකයන් විසින් සිදු කෙරේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e0222af9-21ea-53cf-a1c7-acfcb89cf048', 'b6abf530-2b43-546c-af2e-342932e49ee9', 36, '<p>පහත කවරක් Internet Protocol (IP) ලිපිනයකට නිවැරදි උදාහරණයක් වේද?</p>', '<p>පහත කවරක් Internet Protocol (IP) ලිපිනයකට නිවැරදි උදාහරණයක් වේද?</p>', NULL, 'නිවැරදි IPv4 ලිපිනයක් තිත් (dots) මගින් වෙන් කළ සංඛ්‍යාත්මක කාණ්ඩ 4කින් සමන්විත විය යුතු අතර, ඒ සෑම කාණ්ඩයකම අගය 0 සිට 255 දක්වා පරාසයක පමණක් පැවතිය යුතුය. 4 වන විකල්පය මෙම සියලු කොන්දේසි සපුරයි.', 'නිවැරදි IPv4 ලිපිනයක් තිත් (dots) මගින් වෙන් කළ සංඛ්‍යාත්මක කාණ්ඩ 4කින් සමන්විත විය යුතු අතර, ඒ සෑම කාණ්ඩයකම අගය 0 සිට 255 දක්වා පරාසයක පමණක් පැවතිය යුතුය. 4 වන විකල්පය මෙම සියලු කොන්දේසි සපුරයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
