INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('abf9d4af-d294-5669-9878-be8dce216937', 'ba6caf85-c6c8-53f1-b997-ec4c0d903284', 2, '<p>මැංගනීස් පරමාණුවේ ($Mn$, $Z=25$) $l=0$ සහ $m_{l}=-1$ ක්වොන්ටම් අංක ඇති ඉලෙක්ට්‍රෝන සංඛ්‍යා පිළිවෙළින්.</p>', '<p>මැංගනීස් පරමාණුවේ ($Mn$, $Z=25$) $l=0$ සහ $m_{l}=-1$ ක්වොන්ටම් අංක ඇති ඉලෙක්ට්‍රෝන සංඛ්‍යා පිළිවෙළින්.</p>', NULL, '$Mn$ පරමාණුවේ ඉලෙක්ට්‍රෝන වින්‍යාසය: $1s^2 2s^2 2p^6 3s^2 3p^6 4s^2 3d^5$ වේ.<br>$l=0$ යනු $s$ උපශක්ති මට්ටම් වේ ($1s, 2s, 3s, 4s$). එහි ඇති මුළු ඉලෙක්ට්‍රෝන ගණන = $2+2+2+2 = 8$ කි.<br>$m_l=-1$ විය හැක්කේ $p$, $d$ (සහ $f$) උපශක්ති මට්ටම් වලට පමණි. $2p$ හි 2ක්, $3p$ හි 2ක් සහ $3d$ හි 1ක් ලෙස $m_l=-1$ ඇති ඉලෙක්ට්‍රෝන $2+2+1 = 5$ ක් ඇත. එබැවින් පිළිතුර 8 සහ 5 වේ.', '$Mn$ පරමාණුවේ ඉලෙක්ට්‍රෝන වින්‍යාසය: $1s^2 2s^2 2p^6 3s^2 3p^6 4s^2 3d^5$ වේ.<br>$l=0$ යනු $s$ උපශක්ති මට්ටම් වේ ($1s, 2s, 3s, 4s$). එහි ඇති මුළු ඉලෙක්ට්‍රෝන ගණන = $2+2+2+2 = 8$ කි.<br>$m_l=-1$ විය හැක්කේ $p$, $d$ (සහ $f$) උපශක්ති මට්ටම් වලට පමණි. $2p$ හි 2ක්, $3p$ හි 2ක් සහ $3d$ හි 1ක් ලෙස $m_l=-1$ ඇති ඉලෙක්ට්‍රෝන $2+2+1 = 5$ ක් ඇත. එබැවින් පිළිතුර 8 සහ 5 වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
