INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('290ff66b-7655-425a-aa7b-e43b926228cb', 'bcdba43b-73b3-5ac7-b533-6c0dd7664198', 'එය ඇල්කොහොලයේ C-O බන්ධනය බිඳෙමින් සිදුවන ප්‍රතික්‍රියාවකි.', 'එය ඇල්කොහොලයේ C-O බන්ධනය බිඳෙමින් සිදුවන ප්‍රතික්‍රියාවකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c32da624-9899-4b85-ade3-73eff846c23c', 'bcdba43b-73b3-5ac7-b533-6c0dd7664198', 'එය අම්ල - භස්ම ප්‍රතික්‍රියාවකි.', 'එය අම්ල - භස්ම ප්‍රතික්‍රියාවකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b50bc4e4-4630-520b-b10c-578d20645e56', 'ba6caf85-c6c8-53f1-b997-ec4c0d903284', 21, '<p>ඉහළ උෂ්ණත්වවලදී $CH_{3}OH(l)$ 1 mol ක් පහත පරිදි වියෝජනය වේ.<br><br>$CH_{3}OH(l)\rightarrow CO(g)+2H_{2}(g);\ \Delta H=+128~kJ$<br><br>පහත සඳහන් කුමක් ඉහත ප්‍රතික්‍රියාව සඳහා අසත්‍ය වේ ද? ($H=1, C=12, O=16$)</p>', '<p>ඉහළ උෂ්ණත්වවලදී $CH_{3}OH(l)$ 1 mol ක් පහත පරිදි වියෝජනය වේ.<br><br>$CH_{3}OH(l)\rightarrow CO(g)+2H_{2}(g);\ \Delta H=+128~kJ$<br><br>පහත සඳහන් කුමක් ඉහත ප්‍රතික්‍රියාව සඳහා අසත්‍ය වේ ද? ($H=1, C=12, O=16$)</p>', NULL, 'ප්‍රතික්‍රියාවේ $\Delta H = +128~kJ$ බැවින් එය තාපාවශෝෂක ප්‍රතික්‍රියාවකි (එනම් තාපය අවශෝෂණය වේ). එමනිසා 128 kJ තාපයක් පිටවේ යන ප්‍රකාශය අසත්‍ය වේ. සෙසු ප්‍රකාශ විද්‍යාත්මකව නිවැරදියි: වාෂ්පීකරණයේදී තාපය අවශෝෂණය වන බැවින් $CH_{3}OH(g)$ වියෝජනයේදී අවශෝෂණය වන ශුද්ධ තාපය අඩු වේ, නිෂ්පාදන වල එන්තැල්පිය වැඩි බැවින් $\Delta H > 0$ වේ, සහ $CH_{3}OH$ හි මවුලික ස්කන්ධය 32 g/mol වේ.', 'ප්‍රතික්‍රියාවේ $\Delta H = +128~kJ$ බැවින් එය තාපාවශෝෂක ප්‍රතික්‍රියාවකි (එනම් තාපය අවශෝෂණය වේ). එමනිසා 128 kJ තාපයක් පිටවේ යන ප්‍රකාශය අසත්‍ය වේ. සෙසු ප්‍රකාශ විද්‍යාත්මකව නිවැරදියි: වාෂ්පීකරණයේදී තාපය අවශෝෂණය වන බැවින් $CH_{3}OH(g)$ වියෝජනයේදී අවශෝෂණය වන ශුද්ධ තාපය අඩු වේ, නිෂ්පාදන වල එන්තැල්පිය වැඩි බැවින් $\Delta H > 0$ වේ, සහ $CH_{3}OH$ හි මවුලික ස්කන්ධය 32 g/mol වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('31eaebfc-dd5c-44df-891e-887ce2d11b07', 'b50bc4e4-4630-520b-b10c-578d20645e56', '$CH_{3}OH(g)$ 1 mol වියෝජනය වනවිට අවශෝෂණය වන තාපය 128 kJ ට වඩා අඩු වේ.', '$CH_{3}OH(g)$ 1 mol වියෝජනය වනවිට අවශෝෂණය වන තාපය 128 kJ ට වඩා අඩු වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4164a698-aea1-4f18-b088-69428520e801', 'b50bc4e4-4630-520b-b10c-578d20645e56', '$CO(g)+2H_{2}(g)$ හි එන්තැල්පිය $CH_{3}OH(l)$ හි එන්තැල්පියට වඩා වැඩි වේ.', '$CO(g)+2H_{2}(g)$ හි එන්තැල්පිය $CH_{3}OH(l)$ හි එන්තැල්පියට වඩා වැඩි වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('acecb910-ce77-4447-bf9b-3d1ba907f984', 'b50bc4e4-4630-520b-b10c-578d20645e56', '$CO(g)$ 1 mol සෑදෙන විට 128 kJ ක තාපයක් පිට වේ.', '$CO(g)$ 1 mol සෑදෙන විට 128 kJ ක තාපයක් පිට වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e7b2a4e5-acb0-412b-be88-99ae2712f968', 'b50bc4e4-4630-520b-b10c-578d20645e56', 'ප්‍රතික්‍රියක මවුලයක් වියෝජනයේදී 128 kJ ක තාපයක් අවශෝෂණය වේ.', 'ප්‍රතික්‍රියක මවුලයක් වියෝජනයේදී 128 kJ ක තාපයක් අවශෝෂණය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7b808982-b7a4-4db2-ba83-6a45747aa862', 'b50bc4e4-4630-520b-b10c-578d20645e56', 'ඵල 32 g සෑදෙන විට 128 kJ ක තාපයක් අවශෝෂණය වේ.', 'ඵල 32 g සෑදෙන විට 128 kJ ක තාපයක් අවශෝෂණය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5608d5de-8eda-5413-a511-f4196ca17b8a', 'ba6caf85-c6c8-53f1-b997-ec4c0d903284', 22, '<p>පහත දැක්වෙන ඒවායින් වැරදි ප්‍රකාශය හඳුනාගන්න.</p>', '<p>පහත දැක්වෙන ඒවායින් වැරදි ප්‍රකාශය හඳුනාගන්න.</p>', NULL, 'ඇලුමිනියම් ඉහළ උෂ්ණත්වවලදී නයිට්‍රජන් වායුව සමඟ ප්‍රතික්‍රියා කර ඇලුමිනියම් නයිට්‍රයිඩ් ($AlN$) සාදයි. එබැවින් ඇලුමිනියම් $N_{2}$ කෙරෙහි නිෂ්ක්‍රිය වේ යන ප්‍රකාශය වැරදියි. සෙසු කරුණු නිවැරදියි: $N(g)$ හි ඉලෙක්ට්‍රෝන ඇල්ෆිනිටි අගය ඍණ වුවද, ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය සාම්ප්‍රදායිකව ධන ලෙස දැක්වේ, $BiCl_{3}$ ජලවිච්ඡේදනයෙන් $BiOCl$ සුදු අවක්ෂේපය සෑදේ, $H_{2}S$ හි සල්ෆර් ඔක්සිකරණ අංකය -2 වන බැවින් එයට ඉහළට හෝ පහළට යා හැකිය.', 'ඇලුමිනියම් ඉහළ උෂ්ණත්වවලදී නයිට්‍රජන් වායුව සමඟ ප්‍රතික්‍රියා කර ඇලුමිනියම් නයිට්‍රයිඩ් ($AlN$) සාදයි. එබැවින් ඇලුමිනියම් $N_{2}$ කෙරෙහි නිෂ්ක්‍රිය වේ යන ප්‍රකාශය වැරදියි. සෙසු කරුණු නිවැරදියි: $N(g)$ හි ඉලෙක්ට්‍රෝන ඇල්ෆිනිටි අගය ඍණ වුවද, ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය සාම්ප්‍රදායිකව ධන ලෙස දැක්වේ, $BiCl_{3}$ ජලවිච්ඡේදනයෙන් $BiOCl$ සුදු අවක්ෂේපය සෑදේ, $H_{2}S$ හි සල්ෆර් ඔක්සිකරණ අංකය -2 වන බැවින් එයට ඉහළට හෝ පහළට යා හැකිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('37a4d239-f31c-4a0a-a656-52e825f0c17d', '5608d5de-8eda-5413-a511-f4196ca17b8a', 'නයිට්‍රජන්වල [$N(g)$] ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය ධන වේ.', 'නයිට්‍රජන්වල [$N(g)$] ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය ධන වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a5c0535b-19ea-4dfd-b349-5c3c0b4d1318', '5608d5de-8eda-5413-a511-f4196ca17b8a', '$BiCl_{3}(aq)$ ද්‍රාවණයක් ජලයෙන් තනුක කරන විට සුදු අවක්ෂේපයක් දෙයි.', '$BiCl_{3}(aq)$ ද්‍රාවණයක් ජලයෙන් තනුක කරන විට සුදු අවක්ෂේපයක් දෙයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ea420cae-a6b3-4422-aa52-fa12b5adc84a', '5608d5de-8eda-5413-a511-f4196ca17b8a', '$H_{2}S$ වායුවට ඔක්සිකාරකයක් සහ ඔක්සිහාරකයක් යන දෙආකාරයටම ක්‍රියා කළ හැක.', '$H_{2}S$ වායුවට ඔක්සිකාරකයක් සහ ඔක්සිහාරකයක් යන දෙආකාරයටම ක්‍රියා කළ හැක.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d0f0c0fb-ee89-4c8d-b3b8-628e79605953', '5608d5de-8eda-5413-a511-f4196ca17b8a', 'He වල සංයුජතා ඉලෙක්ට්‍රෝනයකට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණය ($Z^{*}$) 2ට වඩා අඩු ය.', 'He වල සංයුජතා ඉලෙක්ට්‍රෝනයකට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණය ($Z^{*}$) 2ට වඩා අඩු ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8994a280-1aee-4515-aaa2-b7d3fafd2991', '5608d5de-8eda-5413-a511-f4196ca17b8a', 'ඉහළ උෂ්ණත්වයකට රත් කළ වුවද ඇලුමිනියම්, $N_{2}$ වායුව කෙරෙහි නිෂ්ක්‍රිය වේ.', 'ඉහළ උෂ්ණත්වයකට රත් කළ වුවද ඇලුමිනියම්, $N_{2}$ වායුව කෙරෙහි නිෂ්ක්‍රිය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d5c25355-1915-52e5-9dc0-3850e968dc58', 'ba6caf85-c6c8-53f1-b997-ec4c0d903284', 23, '<p>298 K දී දුබල අම්ලයක් වන $HA$ හි තනුක ජලීය ද්‍රාවණයක සාන්ද්‍රණය $C~mol~dm^{-3}$ වන අතර එහි අම්ල විඝටන නියතය $K_{a}$ වේ. මෙම ද්‍රාවණයෙහි $pH$ පහත සඳහන් කුමන ප්‍රකාශනය මගින් ලබාදෙයි ද?</p>', '<p>298 K දී දුබල අම්ලයක් වන $HA$ හි තනුක ජලීය ද්‍රාවණයක සාන්ද්‍රණය $C~mol~dm^{-3}$ වන අතර එහි අම්ල විඝටන නියතය $K_{a}$ වේ. මෙම ද්‍රාවණයෙහි $pH$ පහත සඳහන් කුමන ප්‍රකාශනය මගින් ලබාදෙයි ද?</p>', NULL, 'දුබල අම්ලයක් සඳහා $[H^+] = \sqrt{K_a C}$ වේ. $pH = -log[H^+]$ බැවින්, $pH = -log(K_a C)^{1/2} = -1/2 log K_a - 1/2 log C$ වේ. $pK_a = -log K_a$ බැවින්, $pH = 1/2 pK_a - 1/2 log C$ වේ.', 'දුබල අම්ලයක් සඳහා $[H^+] = \sqrt{K_a C}$ වේ. $pH = -log[H^+]$ බැවින්, $pH = -log(K_a C)^{1/2} = -1/2 log K_a - 1/2 log C$ වේ. $pK_a = -log K_a$ බැවින්, $pH = 1/2 pK_a - 1/2 log C$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('162cb2b6-db60-41dd-9a22-e2d866355c3b', 'd5c25355-1915-52e5-9dc0-3850e968dc58', '$pH=\frac{1}{2}pK_{a}-\frac{1}{2}log~C$', '$pH=\frac{1}{2}pK_{a}-\frac{1}{2}log~C$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('38dd6056-9f54-4ec0-991d-c96b0912d4f0', 'd5c25355-1915-52e5-9dc0-3850e968dc58', '$pH=-\frac{1}{2}pK_{a}-\frac{1}{2}log~C$', '$pH=-\frac{1}{2}pK_{a}-\frac{1}{2}log~C$', NULL, 'sanitized', 'v1', 1, 0);
