INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f219c124-c24c-465f-8ba9-4ca10a6d90d9', 'd5c25355-1915-52e5-9dc0-3850e968dc58', '$pH=-\frac{1}{2}pK_{a}-\frac{1}{2}log(1/C)$', '$pH=-\frac{1}{2}pK_{a}-\frac{1}{2}log(1/C)$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('491b3be6-a60a-498e-b722-4237a1028e87', 'd5c25355-1915-52e5-9dc0-3850e968dc58', '$pH=\frac{1}{2}pK_{a}-\frac{1}{2}log(1/C)$', '$pH=\frac{1}{2}pK_{a}-\frac{1}{2}log(1/C)$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('31794911-28e1-5640-91f5-6b5587920831', 'ba6caf85-c6c8-53f1-b997-ec4c0d903284', 24, '<p>$H_{2}O_{2}$ ද්‍රාවණයක ප්‍රබලතාව, සාමාන්‍ය උෂ්ණත්වයේදී හා පීඩනයේදී (සා.උ.පී.) ලබාදෙන $O_{2}$ වායුවේ පරිමාව අනුව ප්‍රකාශ කළ හැක.<br>උදාහරණයක් වශයෙන්, පරිමා ප්‍රබලතාව 20 වන $H_{2}O_{2}$ (20 volume strength $H_{2}O_{2}$) ද්‍රාවණයකින් ලීටරයක් සා.උ.පී. දී $O_{2}$ ලීටර 20 ක් ලබා දෙයි. ($2H_{2}O_{2}(aq)\rightarrow 2H_{2}O(l)+O_{2}(g)$). (සා.උ.පී. හිදී ලීටර 22.4 ක පරිමාවක් ගන්නා බව උපකල්පනය කරන්න.)<br><br>X ලෙස නම් කර ඇති බෝතලයක $H_{2}O_{2}$ ද්‍රාවණයක් අඩංගු ය. මෙම X ද්‍රාවණයෙන් $25.0~cm^{3}$ තනුක $H_{2}SO_{4}$ හමුවේ $1.0~mol~dm^{-3}~KMnO_{4}$ සමග අනුමාපනය කළවිට, අන්ත ලක්ෂ්‍යය එළඹීමට අවශ්‍ය වූ පරිමාව $25.0~cm^{3}$ විය.<br>X ද්‍රාවණයේ පරිමා ප්‍රබලතාව වනුයේ,</p>', '<p>$H_{2}O_{2}$ ද්‍රාවණයක ප්‍රබලතාව, සාමාන්‍ය උෂ්ණත්වයේදී හා පීඩනයේදී (සා.උ.පී.) ලබාදෙන $O_{2}$ වායුවේ පරිමාව අනුව ප්‍රකාශ කළ හැක.<br>උදාහරණයක් වශයෙන්, පරිමා ප්‍රබලතාව 20 වන $H_{2}O_{2}$ (20 volume strength $H_{2}O_{2}$) ද්‍රාවණයකින් ලීටරයක් සා.උ.පී. දී $O_{2}$ ලීටර 20 ක් ලබා දෙයි. ($2H_{2}O_{2}(aq)\rightarrow 2H_{2}O(l)+O_{2}(g)$). (සා.උ.පී. හිදී ලීටර 22.4 ක පරිමාවක් ගන්නා බව උපකල්පනය කරන්න.)<br><br>X ලෙස නම් කර ඇති බෝතලයක $H_{2}O_{2}$ ද්‍රාවණයක් අඩංගු ය. මෙම X ද්‍රාවණයෙන් $25.0~cm^{3}$ තනුක $H_{2}SO_{4}$ හමුවේ $1.0~mol~dm^{-3}~KMnO_{4}$ සමග අනුමාපනය කළවිට, අන්ත ලක්ෂ්‍යය එළඹීමට අවශ්‍ය වූ පරිමාව $25.0~cm^{3}$ විය.<br>X ද්‍රාවණයේ පරිමා ප්‍රබලතාව වනුයේ,</p>', NULL, 'ප්‍රතික්‍රියාව: $2MnO_{4}^{-} + 6H^{+} + 5H_{2}O_{2} \rightarrow 2Mn^{2+} + 5O_{2} + 8H_{2}O$.<br>$KMnO_{4}$ මවුල = $0.1 \times 0.025 = 0.0025~mol$.<br>$H_{2}O_{2}$ මවුල = $0.0025 \times (5/2) = 0.00625~mol$.<br>$25~cm^{3}$ ද්‍රාවණයක මවුල 0.00625 ක් ඇත. 1 L ද්‍රාවණයක මවුල $0.00625 \times 40 = 0.25~mol$ ඇත.<br>$H_{2}O_{2}$ මවුල $0.25~mol$ මගින් $O_{2}$ මවුල $0.125$ ක් සෑදේ. පරිමාව = $0.125 \times 22.4 = 2.8~L$.<br>පරිමා ප්‍රබලතාව යනු 1 L ද්‍රාවණයකින් සෑදෙන $O_{2}$ පරිමාවයි. මෙහි මවුල සාන්ද්‍රණය මගින් ලැබෙනුයේ පරිමා ප්‍රබලතාව 28 කි (සැලකිය යුතුයි: විභාග දෙපාර්තමේන්තුවේ ලකුණු දීමේ පටිපාටියට අනුව මෙම ප්‍රශ්නයේ සියලුම පිළිතුරු සඳහා ලකුණු ලබා දී ඇත).', 'ප්‍රතික්‍රියාව: $2MnO_{4}^{-} + 6H^{+} + 5H_{2}O_{2} \rightarrow 2Mn^{2+} + 5O_{2} + 8H_{2}O$.<br>$KMnO_{4}$ මවුල = $0.1 \times 0.025 = 0.0025~mol$.<br>$H_{2}O_{2}$ මවුල = $0.0025 \times (5/2) = 0.00625~mol$.<br>$25~cm^{3}$ ද්‍රාවණයක මවුල 0.00625 ක් ඇත. 1 L ද්‍රාවණයක මවුල $0.00625 \times 40 = 0.25~mol$ ඇත.<br>$H_{2}O_{2}$ මවුල $0.25~mol$ මගින් $O_{2}$ මවුල $0.125$ ක් සෑදේ. පරිමාව = $0.125 \times 22.4 = 2.8~L$.<br>පරිමා ප්‍රබලතාව යනු 1 L ද්‍රාවණයකින් සෑදෙන $O_{2}$ පරිමාවයි. මෙහි මවුල සාන්ද්‍රණය මගින් ලැබෙනුයේ පරිමා ප්‍රබලතාව 28 කි (සැලකිය යුතුයි: විභාග දෙපාර්තමේන්තුවේ ලකුණු දීමේ පටිපාටියට අනුව මෙම ප්‍රශ්නයේ සියලුම පිළිතුරු සඳහා ලකුණු ලබා දී ඇත).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
