INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d11fd092-c454-5c7a-ac7f-555df19bd230', 'ba6caf85-c6c8-53f1-b997-ec4c0d903284', 26, '<p>298 K දී සම්මත හයිඩ්‍රජන් ඉලෙක්ට්‍රෝඩයක්, සම්මත Mg -ඉලෙක්ට්‍රෝඩයක් හා ලවණ සේතුවක් භාවිතයෙන් ගොඩනගන ලද සම්මත ගැල්වානි කෝෂයක් පහත සඳහන් කුමක් මගින් නිවැරදිව දැක්වෙයි ද?</p>', '<p>298 K දී සම්මත හයිඩ්‍රජන් ඉලෙක්ට්‍රෝඩයක්, සම්මත Mg -ඉලෙක්ට්‍රෝඩයක් හා ලවණ සේතුවක් භාවිතයෙන් ගොඩනගන ලද සම්මත ගැල්වානි කෝෂයක් පහත සඳහන් කුමක් මගින් නිවැරදිව දැක්වෙයි ද?</p>', NULL, 'ගැල්වානි කෝෂයක ඇනෝඩය වම් පසින් ද, කැතෝඩය දකුණු පසින් ද ලියනු ලැබේ ($A|A^{n+}||B^{n+}|B$). මැග්නීසියම් ($Mg$) සඳහා ඔක්සිකරණ විභවය හයිඩ්‍රජන් වලට වඩා වැඩිය, එබැවින් $Mg$ ඇනෝඩය වේ ($Mg\rightarrow Mg^{2+}+2e^-$). කැතෝඩය හයිඩ්‍රජන් ඉලෙක්ට්‍රෝඩය වේ ($2H^++2e^-\rightarrow H_2$). නිවැරදි නිරූපණය විකල්ප 1 හි ඇත.', 'ගැල්වානි කෝෂයක ඇනෝඩය වම් පසින් ද, කැතෝඩය දකුණු පසින් ද ලියනු ලැබේ ($A|A^{n+}||B^{n+}|B$). මැග්නීසියම් ($Mg$) සඳහා ඔක්සිකරණ විභවය හයිඩ්‍රජන් වලට වඩා වැඩිය, එබැවින් $Mg$ ඇනෝඩය වේ ($Mg\rightarrow Mg^{2+}+2e^-$). කැතෝඩය හයිඩ්‍රජන් ඉලෙක්ට්‍රෝඩය වේ ($2H^++2e^-\rightarrow H_2$). නිවැරදි නිරූපණය විකල්ප 1 හි ඇත.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('25026d2e-4da0-49db-811d-6e938d6e1093', 'd11fd092-c454-5c7a-ac7f-555df19bd230', '$Mg(s)|Mg^{2+}(aq,1.00~mol~dm^{-3})||H^{+}(aq,1.00~mol~dm^{-3})|H_{2}(g)|Pt(s)$', '$Mg(s)|Mg^{2+}(aq,1.00~mol~dm^{-3})||H^{+}(aq,1.00~mol~dm^{-3})|H_{2}(g)|Pt(s)$', NULL, 'sanitized', 'v1', 0, 1);
