INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('46d58778-968e-4f48-9046-bbca9d7115b2', 'd11fd092-c454-5c7a-ac7f-555df19bd230', '$Mg(s)|Mg^{2+}(aq,1.00~mol~dm^{-3}), H^{+}(aq,1.00~mol~dm^{-3}), H_{2}(g)|Pt(s)$', '$Mg(s)|Mg^{2+}(aq,1.00~mol~dm^{-3}), H^{+}(aq,1.00~mol~dm^{-3}), H_{2}(g)|Pt(s)$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3ad3e792-8d79-4c8d-86b7-142f7ff1df05', 'd11fd092-c454-5c7a-ac7f-555df19bd230', '$Pt(s),H_{2}(g)|H^{+}(aq,1.00~mol~dm^{-3})||Mg^{2+}(aq,1.00~mol~dm^{-3}), Mg(s)$', '$Pt(s),H_{2}(g)|H^{+}(aq,1.00~mol~dm^{-3})||Mg^{2+}(aq,1.00~mol~dm^{-3}), Mg(s)$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b610ceed-0dfa-5772-8af7-821fe611f704', 'ba6caf85-c6c8-53f1-b997-ec4c0d903284', 27, '<p>298 K දී ඩයික්ලෝරෝමීතේන් සහ ජලය අතර ඒකභාස්මික කාබනික අම්ලයක ව්‍යාප්ති සංගුණකය $K_{D}$ නිර්ණය කිරීම සඳහා පහත ක්‍රමය භාවිත කරන ලදී.<br><br>$0.20~mol~dm^{-3}$ අම්ලයෙහි ජලීය ද්‍රාවණයකින් $50.00~cm^{3}$ ක් ඩයික්ලෝරෝමීතේන් $10.00~cm^{3}$ ක් සමග හොඳින් මිශ්‍ර කර ස්තර දෙක වෙන් වීමට තබන ලදී.<br>ඉන්පසු ප්ලාස්කුවේ පහළ ඇති ඩයික්ලෝරෝමීතේන් ස්තරය ඉවත් කරන ලදී. ජලීය ස්තරයෙහි ඉතිරිව ඇති අම්ලය උදාසීන කිරීම සඳහා $0.02~mol~dm^{-3}~NaOH(aq)$ ද්‍රාවණයකින් $10.00~cm^{3}$ ක් අවශ්‍ය විය. (කාබනික ස්තරයේදී අම්ලය ද්විඅවයවීකරණය නොවේ යැයි උපකල්පනය කරන්න.) ඩයික්ලෝරෝමීතේන් හා ජලය අතර 298 K දී අම්ලයෙහි $K_{D}$ වනුයේ,</p>', '<p>298 K දී ඩයික්ලෝරෝමීතේන් සහ ජලය අතර ඒකභාස්මික කාබනික අම්ලයක ව්‍යාප්ති සංගුණකය $K_{D}$ නිර්ණය කිරීම සඳහා පහත ක්‍රමය භාවිත කරන ලදී.<br><br>$0.20~mol~dm^{-3}$ අම්ලයෙහි ජලීය ද්‍රාවණයකින් $50.00~cm^{3}$ ක් ඩයික්ලෝරෝමීතේන් $10.00~cm^{3}$ ක් සමග හොඳින් මිශ්‍ර කර ස්තර දෙක වෙන් වීමට තබන ලදී.<br>ඉන්පසු ප්ලාස්කුවේ පහළ ඇති ඩයික්ලෝරෝමීතේන් ස්තරය ඉවත් කරන ලදී. ජලීය ස්තරයෙහි ඉතිරිව ඇති අම්ලය උදාසීන කිරීම සඳහා $0.02~mol~dm^{-3}~NaOH(aq)$ ද්‍රාවණයකින් $10.00~cm^{3}$ ක් අවශ්‍ය විය. (කාබනික ස්තරයේදී අම්ලය ද්විඅවයවීකරණය නොවේ යැයි උපකල්පනය කරන්න.) ඩයික්ලෝරෝමීතේන් හා ජලය අතර 298 K දී අම්ලයෙහි $K_{D}$ වනුයේ,</p>', NULL, 'ආරම්භක අම්ල මවුල = $0.2 \times 0.05 = 0.01~mol$.<br>ඉතිරි වූ අම්ල මවුල = $0.02 \times 0.01 = 0.0002~mol$.<br>කාබනික ස්තරයට ගිය මවුල = $0.01 - 0.0002 = 0.0098~mol$.<br>$[Acid]_{aq} = 0.0002 / 0.05 = 0.004~mol~dm^{-3}$.<br>$[Acid]_{org} = 0.0098 / 0.01 = 0.98~mol~dm^{-3}$.<br>$K_{D} = 0.98 / 0.004 = 245$ .', 'ආරම්භක අම්ල මවුල = $0.2 \times 0.05 = 0.01~mol$.<br>ඉතිරි වූ අම්ල මවුල = $0.02 \times 0.01 = 0.0002~mol$.<br>කාබනික ස්තරයට ගිය මවුල = $0.01 - 0.0002 = 0.0098~mol$.<br>$[Acid]_{aq} = 0.0002 / 0.05 = 0.004~mol~dm^{-3}$.<br>$[Acid]_{org} = 0.0098 / 0.01 = 0.98~mol~dm^{-3}$.<br>$K_{D} = 0.98 / 0.004 = 245$ .', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
