INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bb8522fd-2cde-427f-a089-018d9c6dd9a8', '0a3be8f4-4c4e-5981-952c-2d9f451b22cf', 'රත්නාවලිය, පූජාවලිය, බුත්සරණ, ධර්ම ප්‍රදීපිකාව', 'රත්නාවලිය, පූජාවලිය, බුත්සරණ, ධර්ම ප්‍රදීපිකාව', NULL, 'sanitized', 'v1', 2, 0);
