INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7a687e11-5be5-4b9a-bdc7-61849e56c98a', 'ad58887d-8ebd-51b7-a1a8-784cff88953e', 'සතුරන්ගේ ආක්‍රමණ වලට අප උපක්‍රමශීලී විය යුතු ය.', 'සතුරන්ගේ ආක්‍රමණ වලට අප උපක්‍රමශීලී විය යුතු ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('928d3d46-0457-4ae5-8f77-e2ec32fc6cee', 'ad58887d-8ebd-51b7-a1a8-784cff88953e', 'තොරතුරු යාවත්කාලීන කිරීම රටක ප්‍රගමනයට උපකාරී වෙයි.', 'තොරතුරු යාවත්කාලීන කිරීම රටක ප්‍රගමනයට උපකාරී වෙයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('afaeea10-843b-52ca-8864-0ac00aff631f', 'bb1bb1c7-97f1-5ad0-9172-e04c884ca560', 26, '<p>අංක 26, 27 ප්‍රශ්න යටතේ දක්වා ඇති අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.<br><br>තිබෙන දෙයටත් වඩා අයහපත් දෙයක් ළං කර ගැනීම</p>', '<p>අංක 26, 27 ප්‍රශ්න යටතේ දක්වා ඇති අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.<br><br>තිබෙන දෙයටත් වඩා අයහපත් දෙයක් ළං කර ගැනීම</p>', NULL, '''ඉඟුරු දී මිරිස් ගත්තා වගේ'' යන ප්‍රස්තාව පිරුළින් අදහස් වන්නේ පවතින ගැටලුවකට විසඳුමක් සෙවීමට ගොස් ඊටත් වඩා විශාල කරදරයක හෝ අයහපත් තත්ත්වයකට පත්වීමයි.', '''ඉඟුරු දී මිරිස් ගත්තා වගේ'' යන ප්‍රස්තාව පිරුළින් අදහස් වන්නේ පවතින ගැටලුවකට විසඳුමක් සෙවීමට ගොස් ඊටත් වඩා විශාල කරදරයක හෝ අයහපත් තත්ත්වයකට පත්වීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
