INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e1c42a88-7f8a-426a-a021-490e138976c6', 'afaeea10-843b-52ca-8864-0ac00aff631f', 'ඉස්සෙල්ලා ආපු කනට වඩා පස්සෙ ආපු අඟ ලොකු වුණා වගේ.', 'ඉස්සෙල්ලා ආපු කනට වඩා පස්සෙ ආපු අඟ ලොකු වුණා වගේ.', NULL, 'sanitized', 'v1', 1, 0);
