INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('13a71bdb-dfc3-4e3d-8cde-0f6a37793495', 'b226cef0-e1d6-5b67-b42f-9f5c63ae672c', 'කලක දී වහලු කලක දි රහ වෙනවා ලු.', 'කලක දී වහලු කලක දි රහ වෙනවා ලු.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a3f8a400-525f-446d-8ea2-b75d1fd1b215', 'b226cef0-e1d6-5b67-b42f-9f5c63ae672c', 'ඌරො කැකුණ තළන කොට හබන් කුකුළන්ට රජ මඟුල් ලු.', 'ඌරො කැකුණ තළන කොට හබන් කුකුළන්ට රජ මඟුල් ලු.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('460824fd-434a-5fd5-b612-d44f6cb60ac4', 'bb1bb1c7-97f1-5ad0-9172-e04c884ca560', 28, '<p>ද්විත්ව රූප හා පරරූප සන්ධියට අදාළ නිදසුන් පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', '<p>ද්විත්ව රූප හා පරරූප සන්ධියට අදාළ නිදසුන් පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', NULL, '''සන් + අස් = සන්නස්'' (ද්විත්ව රූප සන්ධි) සහ ''අත් + දැකීම = අද්දැකීම'' (පරරූප සන්ධි - පෙර පදයේ අග අකුර පර පදයේ මුල් අකුරේ ස්වරූපය ගැනීම) නිවැරදි වේ.', '''සන් + අස් = සන්නස්'' (ද්විත්ව රූප සන්ධි) සහ ''අත් + දැකීම = අද්දැකීම'' (පරරූප සන්ධි - පෙර පදයේ අග අකුර පර පදයේ මුල් අකුරේ ස්වරූපය ගැනීම) නිවැරදි වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
