INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3850745c-0fdd-5e35-aeb8-d67b5f9961e2', 'bb1bb1c7-97f1-5ad0-9172-e04c884ca560', 36, '<p>ශ්‍රීමත් අයිවර් ජෙනිංග්ස් මහතා සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය කුමක්ද?</p>', '<p>ශ්‍රීමත් අයිවර් ජෙනිංග්ස් මහතා සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය කුමක්ද?</p>', NULL, 'ශ්‍රීමත් අයිවර් ජෙනිංග්ස් (Sir Ivor Jennings) යනු ශ්‍රී ලංකාවේ ප්‍රථම විශ්වවිද්‍යාලය වන ලංකා විශ්වවිද්‍යාලයේ (University of Ceylon) පළමු උපකුලපතිවරයා හා එහි නිර්මාතෘවරයාය.', 'ශ්‍රීමත් අයිවර් ජෙනිංග්ස් (Sir Ivor Jennings) යනු ශ්‍රී ලංකාවේ ප්‍රථම විශ්වවිද්‍යාලය වන ලංකා විශ්වවිද්‍යාලයේ (University of Ceylon) පළමු උපකුලපතිවරයා හා එහි නිර්මාතෘවරයාය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ac813f5f-ac27-475e-b74b-f5e72c3cdc8c', '3850745c-0fdd-5e35-aeb8-d67b5f9961e2', 'ශ්‍රී ලංකාවේ ජුරාසික යුගය පිළිබඳ තොරතුරු ඉදිරිපත් කළ පුරාවිද්‍යාඥයා ය.', 'ශ්‍රී ලංකාවේ ජුරාසික යුගය පිළිබඳ තොරතුරු ඉදිරිපත් කළ පුරාවිද්‍යාඥයා ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ca5606d4-7132-4a35-97d7-594fe448370e', '3850745c-0fdd-5e35-aeb8-d67b5f9961e2', 'ශ්‍රී ලංකාවේ විශ්ව විද්‍යාල අධ්‍යාපනයේ නිර්මාතෘවරයා ය.', 'ශ්‍රී ලංකාවේ විශ්ව විද්‍යාල අධ්‍යාපනයේ නිර්මාතෘවරයා ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('37f8e671-ac9c-44b1-91c3-a73d7af58ad5', '3850745c-0fdd-5e35-aeb8-d67b5f9961e2', 'පෙරසවි කොන්ක්‍රීට් තාක්ෂණය ලෝකයට හඳුන්වා දුන් ඉංජිනේරුවරයා ය.', 'පෙරසවි කොන්ක්‍රීට් තාක්ෂණය ලෝකයට හඳුන්වා දුන් ඉංජිනේරුවරයා ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f1c35654-dace-41c3-94ed-de50e80de3f3', '3850745c-0fdd-5e35-aeb8-d67b5f9961e2', 'ජාතික ඖෂධ ප්‍රතිපත්තියක් හඳුන්වාදීමට ක්‍රියා කළ විද්වතාය.', 'ජාතික ඖෂධ ප්‍රතිපත්තියක් හඳුන්වාදීමට ක්‍රියා කළ විද්වතාය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('70df5ba8-1f83-5265-a87b-5cdf54f0621a', 'bb1bb1c7-97f1-5ad0-9172-e04c884ca560', 37, '<p>''වගතුග'' නම් තීරු ලිපි මාලාවේ රචකයා කවරෙක් ද?</p>', '<p>''වගතුග'' නම් තීරු ලිපි මාලාවේ රචකයා කවරෙක් ද?</p>', NULL, '''වගතුග'' තීරු ලිපි මාලාව ලංකාදීප පුවත්පතට රචනා කරන ලද්දේ ප්‍රවීණ පුවත්පත් කලාවේදියෙකු හා කවියෙකු වූ ශ්‍රී චන්ද්‍රරත්න මානවසිංහයන් විසිනි.', '''වගතුග'' තීරු ලිපි මාලාව ලංකාදීප පුවත්පතට රචනා කරන ලද්දේ ප්‍රවීණ පුවත්පත් කලාවේදියෙකු හා කවියෙකු වූ ශ්‍රී චන්ද්‍රරත්න මානවසිංහයන් විසිනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
