INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cb8d712a-1dd5-564c-bab0-1633a5c1846f', 'bb1bb1c7-97f1-5ad0-9172-e04c884ca560', 38, '<p>කුඹුරු ගොවිතැනේදී වෑදම යනුවෙන් හඳුන්වන්නේ,</p>', '<p>කුඹුරු ගොවිතැනේදී වෑදම යනුවෙන් හඳුන්වන්නේ,</p>', NULL, 'ගොයම් කැපීම වැනි කෘෂිකාර්මික කටයුතු වල නියැලෙන්නන් සඳහා කෙත් යායේදීම ලබාදෙන ආහාරපාන සංග්‍රහය ''වෑදම'' ලෙස ගොවි වහරේ හැඳින්වේ.', 'ගොයම් කැපීම වැනි කෘෂිකාර්මික කටයුතු වල නියැලෙන්නන් සඳහා කෙත් යායේදීම ලබාදෙන ආහාරපාන සංග්‍රහය ''වෑදම'' ලෙස ගොවි වහරේ හැඳින්වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('df2432b7-39b8-41cf-baa1-73d9b70328bb', 'cb8d712a-1dd5-564c-bab0-1633a5c1846f', 'ගොයම් කැපීමේදී භාවිත කරන දෑකැත්ත යි.', 'ගොයම් කැපීමේදී භාවිත කරන දෑකැත්ත යි.', NULL, 'sanitized', 'v1', 0, 1);
