INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7e18402e-31f7-49a1-b6b5-71b55002fa31', 'cb8d712a-1dd5-564c-bab0-1633a5c1846f', 'ගොයම් එකතු කිරීමට භාවිත කරන පැදුර යි.', 'ගොයම් එකතු කිරීමට භාවිත කරන පැදුර යි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5c996f72-da69-44fe-b59d-5b97e40e355d', 'cb8d712a-1dd5-564c-bab0-1633a5c1846f', 'කමතේ දී සිදු කරන වතාවත් සඳහා භාවිත කරන පූජා භාණ්ඩයි.', 'කමතේ දී සිදු කරන වතාවත් සඳහා භාවිත කරන පූජා භාණ්ඩයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e879f70d-102d-5a4a-8cf7-230b94e736b5', 'bb1bb1c7-97f1-5ad0-9172-e04c884ca560', 39, '<p>''''කසාද කාසිත් ගෙවපු නිසා ඉලන්දාරි ගෑනු ළමයගෙන් යමක් අහන්න තියෙනවා මට'''' හුනුවටයේ කතාවේ එන ඉහත ප්‍රකාශය කරන්නේ කවරකුද?</p>', '<p>''''කසාද කාසිත් ගෙවපු නිසා ඉලන්දාරි ගෑනු ළමයගෙන් යමක් අහන්න තියෙනවා මට'''' හුනුවටයේ කතාවේ එන ඉහත ප්‍රකාශය කරන්නේ කවරකුද?</p>', NULL, 'මෙම දෙබස හෙන්රි ජයසේනයන්ගේ ''හුනුවටයේ කතාව'' නාට්‍යයේ එන සයිමන් ෂෂාවා (ගෘෂාගේ පෙම්වතා) විසින් සිදු කරන ලද්දකි.', 'මෙම දෙබස හෙන්රි ජයසේනයන්ගේ ''හුනුවටයේ කතාව'' නාට්‍යයේ එන සයිමන් ෂෂාවා (ගෘෂාගේ පෙම්වතා) විසින් සිදු කරන ලද්දකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
