INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b39d2901-96b9-46e3-9688-b818425e2e04', '3bbfd588-d513-5696-875a-35bc9b106827', '[රූපයේ (2) මූල ලක්ෂ්‍යය හරහා යන සරල රේඛීය ප්‍රස්තාරය]
