INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bb99a930-b9c0-4979-aec5-325c80aaa9e9', '70b7ed40-bb87-5bf2-a0ab-c170b7e75d0f', '[ඍණ අනුක්‍රමණයක් සහිත සරල රේඛාවක්]
