INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('41f9c3ae-c597-4af5-b1cb-344765d75ea7', 'bad06644-e936-5379-82c1-9834db2e4383', '[වෙනත් S-හැඩයේ ප්‍රස්තාරයක්]
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2c84166d-f83a-5284-a54b-7f3981e39540', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 1, '<p>නිර්ඔක්සිහාරක සීනි වන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', '<p>නිර්ඔක්සිහාරක සීනි වන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', NULL, 'සුක්‍රෝස් ($Sucrose$) යනු නිර්ඔක්සිහාරක (non-reducing) සීනියකි. එහි නිදහස් ඇල්ඩිහයිඩ හෝ කීටෝන කාණ්ඩයක් නොමැත. රයිබෝස්, ගැලැක්ටෝස් වැනි මොනොසැකරයිඩ සහ මෝල්ටෝස්, ලැක්ටෝස් වැනි අනෙකුත් ඩයිසැකරයිඩ ඔක්සිකාරක සීනි වේ.', 'සුක්‍රෝස් ($Sucrose$) යනු නිර්ඔක්සිහාරක (non-reducing) සීනියකි. එහි නිදහස් ඇල්ඩිහයිඩ හෝ කීටෝන කාණ්ඩයක් නොමැත. රයිබෝස්, ගැලැක්ටෝස් වැනි මොනොසැකරයිඩ සහ මෝල්ටෝස්, ලැක්ටෝස් වැනි අනෙකුත් ඩයිසැකරයිඩ ඔක්සිකාරක සීනි වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
