INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('01aff357-9f49-49db-943f-1dceb7f7404a', '2c84166d-f83a-5284-a54b-7f3981e39540', 'සුක්‍රෝස්', 'සුක්‍රෝස්', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4838b6dd-3c4a-53d9-85f0-5b1592fae9fa', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 2, '<p>ප්ලාස්ම පටලය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ප්ලාස්ම පටලය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'තරල විචිත්‍ර ආකෘතියට (Fluid Mosaic Model) අනුව පොස්පොලිපිඩ අණු වලට පාර්ශ්විකව චලනය විය හැකි අතර, මෙමගින් ප්ලාස්ම පටලයට තරලමය ස්වභාවයක් (fluidity) ලැබේ.', 'තරල විචිත්‍ර ආකෘතියට (Fluid Mosaic Model) අනුව පොස්පොලිපිඩ අණු වලට පාර්ශ්විකව චලනය විය හැකි අතර, මෙමගින් ප්ලාස්ම පටලයට තරලමය ස්වභාවයක් (fluidity) ලැබේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c8b8d3f4-26d2-410a-b16d-fc8ab864c38f', '4838b6dd-3c4a-53d9-85f0-5b1592fae9fa', 'එය ප්‍රධාන වශයෙන්ම තැනී ඇත්තේ කාබෝහයිඩ්‍රේට, පොස්පොලිපිඩ සහ ප්‍රෝටීන වලිනි.', 'එය ප්‍රධාන වශයෙන්ම තැනී ඇත්තේ කාබෝහයිඩ්‍රේට, පොස්පොලිපිඩ සහ ප්‍රෝටීන වලිනි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2ca93fa4-66d8-4723-b2a2-3bbf651e0252', '4838b6dd-3c4a-53d9-85f0-5b1592fae9fa', 'පොස්පොලිපිඩ අණුවලට චලනය විය හැකි අතර පටලයට තරලමය ස්වභාවයක් ලබා දෙයි.', 'පොස්පොලිපිඩ අණුවලට චලනය විය හැකි අතර පටලයට තරලමය ස්වභාවයක් ලබා දෙයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5dfa3558-590e-4a94-b231-5a478a7cf073', '4838b6dd-3c4a-53d9-85f0-5b1592fae9fa', 'පර්යන්ත ප්‍රෝටීන, පටලයේ පිටත පෘෂ්ඨයට තදින් බැඳී ඇත.', 'පර්යන්ත ප්‍රෝටීන, පටලයේ පිටත පෘෂ්ඨයට තදින් බැඳී ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6dc90047-f509-4280-aaf9-f3efb5864282', '4838b6dd-3c4a-53d9-85f0-5b1592fae9fa', 'පොස්පොලිපිඩ ද්විත්ව ස්තරය, ආසන්න සෛලවලට එකිනෙක සමග සන්නිවේදනය සිදු කර ගැනීම සඳහා උපකාරී වේ.', 'පොස්පොලිපිඩ ද්විත්ව ස්තරය, ආසන්න සෛලවලට එකිනෙක සමග සන්නිවේදනය සිදු කර ගැනීම සඳහා උපකාරී වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('96886038-e92a-42b1-8552-5e159a2bb1c2', '4838b6dd-3c4a-53d9-85f0-5b1592fae9fa', 'පොස්පොලිපිඩවල ජලභීතික වලිග, සෛල සැකිල්ලේ තන්තුවලට සම්බන්ධ වී සෛලයේ හැඩය පවත්වා ගැනීමට උපකාරි වේ.', 'පොස්පොලිපිඩවල ජලභීතික වලිග, සෛල සැකිල්ලේ තන්තුවලට සම්බන්ධ වී සෛලයේ හැඩය පවත්වා ගැනීමට උපකාරි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a32db325-586f-5170-a801-80d53d6c81ab', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 3, '<p>නිවැරදි ''උපසෛලීය සංඝටකය - කෘත්‍යය'' සංකලනය තෝරන්න.</p>', '<p>නිවැරදි ''උපසෛලීය සංඝටකය - කෘත්‍යය'' සංකලනය තෝරන්න.</p>', NULL, 'සිනිඳු අන්තඃප්ලාස්මීය ජාලිකාව (SER) මගින් පරිවහන ආශයිකා නිපදවීම සිදු වේ.<br><br>සටහන: ලකුණු දීමේ පටිපාටියට අනුව (5) වන පිළිතුර වන ''පෙරොක්සිසෝම - ප්‍රභාශ්වසනය'' ද නිවැරදි පිළිතුරක් ලෙස සැලකේ.', 'සිනිඳු අන්තඃප්ලාස්මීය ජාලිකාව (SER) මගින් පරිවහන ආශයිකා නිපදවීම සිදු වේ.<br><br>සටහන: ලකුණු දීමේ පටිපාටියට අනුව (5) වන පිළිතුර වන ''පෙරොක්සිසෝම - ප්‍රභාශ්වසනය'' ද නිවැරදි පිළිතුරක් ලෙස සැලකේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('58073231-e6bf-40c8-9788-519549241719', 'a32db325-586f-5170-a801-80d53d6c81ab', 'ග්ලයොක්සිසෝම - අවශේෂ ද්‍රව්‍ය සෛලයෙන් පිටතට පරිවහනය කිරීම', 'ග්ලයොක්සිසෝම - අවශේෂ ද්‍රව්‍ය සෛලයෙන් පිටතට පරිවහනය කිරීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0ddcc905-184e-4c36-ae76-ef559771c1d7', 'a32db325-586f-5170-a801-80d53d6c81ab', 'සිනිඳු අන්තඃප්ලාස්මීය ජාලිකාව - පරිවහන ආශයිකා නිපදවීම', 'සිනිඳු අන්තඃප්ලාස්මීය ජාලිකාව - පරිවහන ආශයිකා නිපදවීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('75085068-79ed-4f45-961f-dd4e5f182604', 'a32db325-586f-5170-a801-80d53d6c81ab', 'රළු අන්තඃප්ලාස්මීය ජාලිකාව - කාබෝහයිඩ්‍රේට පරිවෘත්තිය', 'රළු අන්තඃප්ලාස්මීය ජාලිකාව - කාබෝහයිඩ්‍රේට පරිවෘත්තිය', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f72c6334-9694-4323-a594-e5af48362f4d', 'a32db325-586f-5170-a801-80d53d6c81ab', 'න්‍යෂ්ටිය - ග්ලයිකොප්‍රෝටීන සංශ්ලේෂණය', 'න්‍යෂ්ටිය - ග්ලයිකොප්‍රෝටීන සංශ්ලේෂණය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b1b46ec7-a0a2-47bc-a607-cd48c002c6ab', 'a32db325-586f-5170-a801-80d53d6c81ab', 'පෙරොක්සිසෝම - ප්‍රභාශ්වසනය', 'පෙරොක්සිසෝම - ප්‍රභාශ්වසනය', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('60eb4da0-dd3a-595e-b5ce-e578ddebbd52', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 4, '<p>ඌනන විභාජනයේ සිදුවීම් හතරක් පහත දී ඇත.<br><br>A - කේන්ද්‍ර දේහ, තර්කුව සාදමින් ප්‍රතිවිරුද්ධ ධ්‍රැව දෙසට ගමන් කිරීම<br>B - උපාගම සංකීර්ණය සෑදීම<br>C - සමජාත වර්ණදේහ යුගල් යෝග කලා තලය මත සකස් වීම<br>D - වර්ණ දේහාංශවල අවතරණය<br><br>ඉහත දැක්වෙන සිදුවීම් වල නිවැරදි අනුපිළිවෙළ වන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', '<p>ඌනන විභාජනයේ සිදුවීම් හතරක් පහත දී ඇත.<br><br>A - කේන්ද්‍ර දේහ, තර්කුව සාදමින් ප්‍රතිවිරුද්ධ ධ්‍රැව දෙසට ගමන් කිරීම<br>B - උපාගම සංකීර්ණය සෑදීම<br>C - සමජාත වර්ණදේහ යුගල් යෝග කලා තලය මත සකස් වීම<br>D - වර්ණ දේහාංශවල අවතරණය<br><br>ඉහත දැක්වෙන සිදුවීම් වල නිවැරදි අනුපිළිවෙළ වන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', NULL, 'ඌනන විභාජනයේ ප්‍රාක්කලාව I හිදී මුලින්ම උපාගම සංකීර්ණය සෑදීම (B) සිදුවේ. ඉන්පසු වර්ණ දේහාංශවල අවතරණය හෙවත් ජාන හුවමාරුව (D) සිදුවේ. ඉන්පසු කේන්ද්‍ර දේහ ප්‍රතිවිරුද්ධ ධ්‍රැව දෙසට ගමන් කරමින් තර්කුව සාදයි (A). ඉන්පසු යෝග කලාව I හිදී සමජාත වර්ණ දේහ යෝග කලා තලය මත සකස් වේ (C).<br>එබැවින් නිවැරදි අනුපිළිවෙළ B, D, A, C වේ.', 'ඌනන විභාජනයේ ප්‍රාක්කලාව I හිදී මුලින්ම උපාගම සංකීර්ණය සෑදීම (B) සිදුවේ. ඉන්පසු වර්ණ දේහාංශවල අවතරණය හෙවත් ජාන හුවමාරුව (D) සිදුවේ. ඉන්පසු කේන්ද්‍ර දේහ ප්‍රතිවිරුද්ධ ධ්‍රැව දෙසට ගමන් කරමින් තර්කුව සාදයි (A). ඉන්පසු යෝග කලාව I හිදී සමජාත වර්ණ දේහ යෝග කලා තලය මත සකස් වේ (C).<br>එබැවින් නිවැරදි අනුපිළිවෙළ B, D, A, C වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_ht