INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c6422323-c558-4a1b-89f1-a31d8f7a546c', 'b457f8fb-0b85-5846-8ba6-7745b4c5a458', 'කැරොටිනොයිඩ සහ ක්ලෝරොෆිල් a එකම තරංග ආයාමයන්ට අදාළ ආලෝකය අවශෝෂණය කරයි.', 'කැරොටිනොයිඩ සහ ක්ලෝරොෆිල් a එකම තරංග ආයාමයන්ට අදාළ ආලෝකය අවශෝෂණය කරයි.', NULL, 'sanitized', 'v1', 3, 0);
