INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c614ce49-7687-4340-b1a5-324588add2b4', 'e6c2f439-4614-56cc-b322-83972c4870a0', 'රේඛීය ඉලෙක්ට්‍රෝන ගලනයේදී ජලය විච්ඡේදනය වීමෙන් ප්‍රභාපද්ධති I ඉලෙක්ට්‍රෝන ලබාගනී.', 'රේඛීය ඉලෙක්ට්‍රෝන ගලනයේදී ජලය විච්ඡේදනය වීමෙන් ප්‍රභාපද්ධති I ඉලෙක්ට්‍රෝන ලබාගනී.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e666f462-b1d2-49fe-866a-6e8befd8b957', 'e6c2f439-4614-56cc-b322-83972c4870a0', 'ප්‍රභාපද්ධති I හි ප්‍රාථමික ඉලෙක්ට්‍රෝන ප්‍රතිග්‍රාහකයාගේ ඇති උද්දීපනය වූ ඉලෙක්ට්‍රෝන, ඉලෙක්ට්‍රෝන ප්‍රතිග්‍රාහක ශ්‍රේණියක් හරහා ප්‍රභාපද්ධති II ට ගමන් කරයි.', 'ප්‍රභාපද්ධති I හි ප්‍රාථමික ඉලෙක්ට්‍රෝන ප්‍රතිග්‍රාහකයාගේ ඇති උද්දීපනය වූ ඉලෙක්ට්‍රෝන, ඉලෙක්ට්‍රෝන ප්‍රතිග්‍රාහක ශ්‍රේණියක් හරහා ප්‍රභාපද්ධති II ට ගමන් කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('14c9ea27-1856-5d05-8897-60846c500088', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 7, '<p>ඩාවින් - වොලස් වාදය පැහැදිලි කිරීමේදී වඩාත්ම වැදගත් වන්නේ පහත සඳහන් කුමන ප්‍රකාශය ද?</p>', '<p>ඩාවින් - වොලස් වාදය පැහැදිලි කිරීමේදී වඩාත්ම වැදගත් වන්නේ පහත සඳහන් කුමන ප්‍රකාශය ද?</p>', NULL, 'ඩාවින්-වොලස් පරිණාමවාදයේ මූලික නිරීක්ෂණයක් සහ පදනමක් වන්නේ, සෑම විශේෂයක්ම පරිසරයට දරා ගත හැකි ප්‍රමාණයට වඩා වැඩි ජනිතයින් සංඛ්‍යාවක් නිපදවීමයි (අධිජනනය / Overproduction).', 'ඩාවින්-වොලස් පරිණාමවාදයේ මූලික නිරීක්ෂණයක් සහ පදනමක් වන්නේ, සෑම විශේෂයක්ම පරිසරයට දරා ගත හැකි ප්‍රමාණයට වඩා වැඩි ජනිතයින් සංඛ්‍යාවක් නිපදවීමයි (අධිජනනය / Overproduction).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8012d94d-6a1b-416a-a91c-7b49d7262937', '14c9ea27-1856-5d05-8897-60846c500088', 'ජීවීහු තම ජීවිත කාලය තුළදී පරිසරයේ අවශ්‍යතාවලට ගැළපෙන පරිදි උචිත අනුවර්තන ඇති කර ගනිති.', 'ජීවීහු තම ජීවිත කාලය තුළදී පරිසරයේ අවශ්‍යතාවලට ගැළපෙන පරිදි උචිත අනුවර්තන ඇති කර ගනිති.', NULL, 'sanitized', 'v1', 0, 1);
