INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('435d91a8-541a-4b4e-95e6-2fd3facfc0ce', '14c9ea27-1856-5d05-8897-60846c500088', 'සෑම විශේෂයක්ම පරිසරයට දරා ගත හැකි ප්‍රමාණයට වඩා වැඩි ජනිතයින් සංඛ්‍යාවක් නිපදවයි.', 'සෑම විශේෂයක්ම පරිසරයට දරා ගත හැකි ප්‍රමාණයට වඩා වැඩි ජනිතයින් සංඛ්‍යාවක් නිපදවයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e233d20a-711e-4d65-862c-4c1169bf96a6', '14c9ea27-1856-5d05-8897-60846c500088', 'අනුවර්තන නිසා ප්‍රවේණික ද්‍රව්‍ය වල වෙනස් වීම් සිදු වේ.', 'අනුවර්තන නිසා ප්‍රවේණික ද්‍රව්‍ය වල වෙනස් වීම් සිදු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4be448fd-44ac-5774-b1af-c07004eed291', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 8, '<p>වක්‍රාකාර වර්ණදේහ, DNA සමග බැඳුණු හිස්ටෝන සහ ආකාර කිහිපයක RNA පොලිමරේස සහිත ගණ තුනක් වන්නේ පිළිවෙළින්</p>', '<p>වක්‍රාකාර වර්ණදේහ, DNA සමග බැඳුණු හිස්ටෝන සහ ආකාර කිහිපයක RNA පොලිමරේස සහිත ගණ තුනක් වන්නේ පිළිවෙළින්</p>', NULL, 'බැක්ටීරියා සහ ආකියා යන දෙගොල්ලන්ටම වක්‍රාකාර වර්ණ දේහ (Circular chromosomes) ඇත (උදා: ආකියාවෙකු වන $Thermococcus$). DNA සමඟ බැඳුණු හිස්ටෝන ප්‍රෝටීන ආකියා සහ සුන්‍යෂ්ටිකයින්ට ඇත (උදා: සුන්‍යෂ්ටිකයෙකු වන $Amoeba$). ආකාර කිහිපයක $RNA$ පොලිමරේස එන්සයිම ආකියා සහ සුන්‍යෂ්ටිකයින් සතුව ඇත (උදා: ආකියාවෙකු වන $Methanococcus$).', 'බැක්ටීරියා සහ ආකියා යන දෙගොල්ලන්ටම වක්‍රාකාර වර්ණ දේහ (Circular chromosomes) ඇත (උදා: ආකියාවෙකු වන $Thermococcus$). DNA සමඟ බැඳුණු හිස්ටෝන ප්‍රෝටීන ආකියා සහ සුන්‍යෂ්ටිකයින්ට ඇත (උදා: සුන්‍යෂ්ටිකයෙකු වන $Amoeba$). ආකාර කිහිපයක $RNA$ පොලිමරේස එන්සයිම ආකියා සහ සුන්‍යෂ්ටිකයින් සතුව ඇත (උදා: ආකියාවෙකු වන $Methanococcus$).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
