INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5b0aecb3-c3e8-438b-9e93-a7ea5a807ff7', 'a0216eda-3660-58b1-a272-6082ab81d325', 'A සහ B යන දෙක ම නිවැරදි අතර B මගින් A තහවුරු නොකෙරේ.', 'A සහ B යන දෙක ම නිවැරදි අතර B මගින් A තහවුරු නොකෙරේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5c2682d6-ae03-585c-a294-1d9721c7fead', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 10, '<p>ප්‍රෝටිස්ටාවන්ගේ දක්නට ලැබෙන ව්‍යුහ හතරක් පහත දැක් වේ.<br><br>A - බහුසෛලික තලස<br>B - සංකෝචක රික්තකය<br>C - ඡවිකාව<br>D - සෛල බිත්තිය<br><br>A, B, C සහ D සහිත ජීවීන් වන්නේ පිළිවෙළින්,</p>', '<p>ප්‍රෝටිස්ටාවන්ගේ දක්නට ලැබෙන ව්‍යුහ හතරක් පහත දැක් වේ.<br><br>A - බහුසෛලික තලස<br>B - සංකෝචක රික්තකය<br>C - ඡවිකාව<br>D - සෛල බිත්තිය<br><br>A, B, C සහ D සහිත ජීවීන් වන්නේ පිළිවෙළින්,</p>', NULL, 'හරිත ඇල්ගී විශේෂයක් වන $Ulva$ සතුව බහුසෛලික තලසක් පවතී. $Euglena$ සතුව ආශ්‍රැති යාමනය සඳහා සංකෝචක රික්තක ඇත. $Paramecium$ සතුව හැඩය පවත්වා ගැනීමට ඡවිකාවක් (Pellicle) ඇත. රතු ඇල්ගී විශේෂයක් වන $Gelidium$ සතුව සෛල බිත්තියක් පවතී.', 'හරිත ඇල්ගී විශේෂයක් වන $Ulva$ සතුව බහුසෛලික තලසක් පවතී. $Euglena$ සතුව ආශ්‍රැති යාමනය සඳහා සංකෝචක රික්තක ඇත. $Paramecium$ සතුව හැඩය පවත්වා ගැනීමට ඡවිකාවක් (Pellicle) ඇත. රතු ඇල්ගී විශේෂයක් වන $Gelidium$ සතුව සෛල බිත්තියක් පවතී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
