INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fd589851-38d2-486b-8aa7-33c285ad764b', '6bd959c4-1e79-56b1-aaec-18da41ce4a80', 'ප්‍රධාන වශයෙන්ම සෛල මාධ්‍ය ප්‍රතිශක්තිය සඳහා වැදගත් වේ.', 'ප්‍රධාන වශයෙන්ම සෛල මාධ්‍ය ප්‍රතිශක්තිය සඳහා වැදගත් වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ef80a733-3ad8-4d93-beef-deba0faa7f8c', '6bd959c4-1e79-56b1-aaec-18da41ce4a80', 'ස්වභාවිකව පරිජිත සක්‍රිය ප්‍රතිශක්තිය සඳහා දායක නොවේ.', 'ස්වභාවිකව පරිජිත සක්‍රිය ප්‍රතිශක්තිය සඳහා දායක නොවේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3a23ff45-3f6c-4166-9cc1-86ad1b4b0009', '6bd959c4-1e79-56b1-aaec-18da41ce4a80', 'ස්වභාවික නාශක සෛල සහ ආධාරක සෛල බවට විභේදනය විය හැකි ය.', 'ස්වභාවික නාශක සෛල සහ ආධාරක සෛල බවට විභේදනය විය හැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('64147c79-d9e8-40f5-9110-4db3afffdd61', '6bd959c4-1e79-56b1-aaec-18da41ce4a80', 'ප්ලාස්ම පටලය මත ප්‍රතිදේහජනක ප්‍රතිග්‍රාහක දරයි.', 'ප්ලාස්ම පටලය මත ප්‍රතිදේහජනක ප්‍රතිග්‍රාහක දරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('79745e7d-e636-5443-a865-60ebe7cb74c7', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 23, '<p>ක්‍රස්ටේශියාවන්ගේ, ඇනලිඩාවන්ගේ සහ පැතලි පණුවන්ගේ බහිස්ස්‍රාවී ව්‍යුහ පිළිවෙළින්</p>', '<p>ක්‍රස්ටේශියාවන්ගේ, ඇනලිඩාවන්ගේ සහ පැතලි පණුවන්ගේ බහිස්ස්‍රාවී ව්‍යුහ පිළිවෙළින්</p>', NULL, 'ක්‍රස්ටේසියාවන්ගේ (උදා: කකුළුවන්, ඉස්සන්) බහිස්ස්‍රාවී ව්‍යුහය හරිත ග්‍රන්ථියයි (Green glands / Antennal glands). ඇනලිඩාවන්ගේ (උදා: ගැඩවිලා) ප්‍රධාන බහිස්ස්‍රාවී අවයව වෘක්කිකා (Metanephridia) වේ. පැතලි පණුවන්ගේ (Platyhelminthes) බහිස්ස්‍රාවය සඳහා සිළු බල්බ (Flame bulbs / Protonephridia) ඇත.', 'ක්‍රස්ටේසියාවන්ගේ (උදා: කකුළුවන්, ඉස්සන්) බහිස්ස්‍රාවී ව්‍යුහය හරිත ග්‍රන්ථියයි (Green glands / Antennal glands). ඇනලිඩාවන්ගේ (උදා: ගැඩවිලා) ප්‍රධාන බහිස්ස්‍රාවී අවයව වෘක්කිකා (Metanephridia) වේ. පැතලි පණුවන්ගේ (Platyhelminthes) බහිස්ස්‍රාවය සඳහා සිළු බල්බ (Flame bulbs / Protonephridia) ඇත.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
