INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('828db147-7975-482f-971b-3559d0a97da7', '79745e7d-e636-5443-a865-60ebe7cb74c7', 'ලවණ ග්‍රන්ථි, සිළු බල්බ සහ වෘක්කිකා වේ.', 'ලවණ ග්‍රන්ථි, සිළු බල්බ සහ වෘක්කිකා වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6b68aba8-7c85-4392-a906-c35f3217ca05', '79745e7d-e636-5443-a865-60ebe7cb74c7', 'හරිත ග්‍රන්ථි, වෘක්කිකා සහ සිළු බල්බ වේ.', 'හරිත ග්‍රන්ථි, වෘක්කිකා සහ සිළු බල්බ වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('360f77c1-164a-505f-bae8-7ed68ecec1d9', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 24, '<p>මිනිස් මොළය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් මොළය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'මස්තිෂ්ක වෘන්තය (Brain stem) සෑදී ඇත්තේ මධ්‍ය මොළය, පෝන්සය සහ සුෂුම්නා ශීර්ෂකය යන කොටස් වලිනි. මේවා කලල අවස්ථාවේදී මධ්‍ය මොළයෙන් හා අපර මොළයෙන් විකසනය වේ.<br><br>දෘෂ්ටික ප්‍රදේශ අපරකපාල ඛණ්ඩිකාවේ ඇත. 4 වන කෝෂිකාව අපර මොළයේ ඇත. කැලෝස දේහයෙන් සම්බන්ධ වන්නේ මස්තිෂ්ක අර්ධ ගෝලයි. නින්ද හා අවදි වීමේ චක්‍ර යාමනයට ප්‍රධාන වන්නේ පයිනියල් ග්‍රන්ථිය (මෙලටොනින්) සහ හයිපොතැලමසයි.', 'මස්තිෂ්ක වෘන්තය (Brain stem) සෑදී ඇත්තේ මධ්‍ය මොළය, පෝන්සය සහ සුෂුම්නා ශීර්ෂකය යන කොටස් වලිනි. මේවා කලල අවස්ථාවේදී මධ්‍ය මොළයෙන් හා අපර මොළයෙන් විකසනය වේ.<br><br>දෘෂ්ටික ප්‍රදේශ අපරකපාල ඛණ්ඩිකාවේ ඇත. 4 වන කෝෂිකාව අපර මොළයේ ඇත. කැලෝස දේහයෙන් සම්බන්ධ වන්නේ මස්තිෂ්ක අර්ධ ගෝලයි. නින්ද හා අවදි වීමේ චක්‍ර යාමනයට ප්‍රධාන වන්නේ පයිනියල් ග්‍රන්ථිය (මෙලටොනින්) සහ හයිපොතැලමසයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b9d92a27-bed8-4be7-b161-7f8c87f4a3c0', '360f77c1-164a-505f-bae8-7ed68ecec1d9', 'මස්තිෂ්ක වෘන්තය කලල මධ්‍ය මොළයෙන් සහ අපර මොළයෙන් විකසනය වේ.', 'මස්තිෂ්ක වෘන්තය කලල මධ්‍ය මොළයෙන් සහ අපර මොළයෙන් විකසනය වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('355c4c14-0463-4c3b-87de-f616b85f1f0c', '360f77c1-164a-505f-bae8-7ed68ecec1d9', 'දෘෂ්ටික සංවේදී ප්‍රදේශ, මස්තිෂ්ක බාහිකයේ ලලාට ඛණ්ඩිකා තුළ පිහිටයි.', 'දෘෂ්ටික සංවේදී ප්‍රදේශ, මස්තිෂ්ක බාහිකයේ ලලාට ඛණ්ඩිකා තුළ පිහිටයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d24a0ade-e975-4aef-b994-e7652446a9f2', '360f77c1-164a-505f-bae8-7ed68ecec1d9', 'මධ්‍ය මොළය තුළ හතර වැනි මස්තිෂ්ක කෝෂිකාව ඇත.', 'මධ්‍ය මොළය තුළ හතර වැනි මස්තිෂ්ක කෝෂිකාව ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c82380c5-8dbc-494c-a6a0-dbcf69099690', '360f77c1-164a-505f-bae8-7ed68ecec1d9', 'අනුමස්තිෂ්කයේ අර්ධගෝල දෙක කැලෝස දේහය මගින් සම්බන්ධ වේ.', 'අනුමස්තිෂ්කයේ අර්ධගෝල දෙක කැලෝස දේහය මගින් සම්බන්ධ වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1f95aae0-4658-422f-8348-a468c09505d0', '360f77c1-164a-505f-bae8-7ed68ecec1d9', 'තැලමස, නින්ද සහ අවදි වීමේ චක්‍ර යාමනය කරයි.', 'තැලමස, නින්ද සහ අවදි වීමේ චක්‍ර යාමනය කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4e529110-528b-57e1-bcf7-8a0b2f4ce7ad', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 25, '<p>නියුරෝනයක පටල විභවය දේහලීය අගයට වඩා ධන අගයකට වෙනස් වූ විට ඇතිවන සිදුවීම් පහත දැක්වේ.<br><br>A: $K^+$ නාලිකා විවෘත වී $K^+$ පිටතට ගලා යෑම<br>B : $Na^+$ නාලිකා විවෘත වී $Na^+$ ඇතුළට ගලා ඒම<br>C: පටලය ප්‍රතිධ්‍රැවනය වීම<br>D: පටලය විධ්‍රැවනය වීම<br><br>ඉහත සිදුවීම් වල නිවැරදි අනුපිළිවෙළ තෝරන්න.</p>', '<p>නියුරෝනයක පටල විභවය දේහලීය අගයට වඩා ධන අගයකට වෙනස් වූ විට ඇතිවන සිදුවීම් පහත දැක්වේ.<br><br>A: $K^+$ නාලිකා විවෘත වී $K^+$ පිටතට ගලා යෑම<br>B : $Na^+$ නාලිකා විවෘත වී $Na^+$ ඇතුළට ගලා ඒම<br>C: පටලය ප්‍රතිධ්‍රැවනය වීම<br>D: පටලය විධ්‍රැවනය වීම<br><br>ඉහත සිදුවීම් වල නිවැරදි අනුපිළිවෙළ තෝරන්න.</p>', NULL, 'පටල විභවය දේහලීය අගයට වඩා වැඩි වූ විට මුලින්ම වෝල්ටීයතා ද්වාර $Na^+$ නාලිකා විවෘත වී $Na^+$ සෛලය තුළට වේගයෙන් ගලා එයි (B). මේ නිසා පටලය විධ්‍රැවනය වේ (D). ඉන්පසුව $Na^+$ නාලිකා වැසී වෝල්ටීයතා ද්වාර $K^+$ නාලිකා විවෘත වී $K^+$ සෛලයෙන් පිටතට ගලා යයි (A). මේ නිසා පටලය යළිත් ප්‍රතිධ්‍රැවනය වීම (C) සිදුවේ.', 'පටල විභවය දේහලීය අගයට වඩා වැඩි වූ විට මුලින්ම වෝල්ටීයතා ද්වාර $Na^+$ නාලිකා විවෘත වී $Na^+$ සෛලය තුළට වේගයෙන් ගලා එයි (B). මේ නිසා පටලය විධ්‍රැවනය වේ (D). ඉන්පසුව $Na^+$ නාලිකා වැසී වෝල්ටීයතා ද්වාර $K^+$ නාලිකා විවෘත වී $K^+$ සෛලයෙන් පිටතට ගලා යයි (A). මේ නිසා පටලය යළිත් ප්‍රතිධ්‍රැවනය වීම (C) සිදුවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
