INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('994353db-6ca4-532e-b3c3-8ca1d7c43335', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 26, '<p>හෝමෝනය සහ එහි ප්‍රධාන කෘත්‍යයේ නිවැරදි ගැළපීම දක්වන ප්‍රතිචාරය තෝරන්න.</p>', '<p>හෝමෝනය සහ එහි ප්‍රධාන කෘත්‍යයේ නිවැරදි ගැළපීම දක්වන ප්‍රතිචාරය තෝරන්න.</p>', NULL, 'තයිරොක්සින් හෝමෝනය මගින් දේහයේ මූලික පරිවෘත්තීය වේගය (BMR) වැඩි කරයි.<br>ඇඩ්‍රිනලින් කෙටිකාලීන ආතති ප්‍රතිචාර වලට ද, ප්‍රොලැක්ටින් කිරි නිෂ්පාදනයට ද (විසර්ජනයට ඔක්සිටොසින්), LH (ලූටිනිකාරක හෝමෝනය) ටෙස්ටොස්ටෙරෝන් ස්‍රාවය සඳහා ලේඩිග් සෛල උත්තේජනයට ද දායක වේ.', 'තයිරොක්සින් හෝමෝනය මගින් දේහයේ මූලික පරිවෘත්තීය වේගය (BMR) වැඩි කරයි.<br>ඇඩ්‍රිනලින් කෙටිකාලීන ආතති ප්‍රතිචාර වලට ද, ප්‍රොලැක්ටින් කිරි නිෂ්පාදනයට ද (විසර්ජනයට ඔක්සිටොසින්), LH (ලූටිනිකාරක හෝමෝනය) ටෙස්ටොස්ටෙරෝන් ස්‍රාවය සඳහා ලේඩිග් සෛල උත්තේජනයට ද දායක වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e9ba39f4-9909-41fe-90af-350bfe3439e7', '994353db-6ca4-532e-b3c3-8ca1d7c43335', 'ඇඩ්‍රිනලින් - දීර්ඝකාලීන ආතති ප්‍රතිචාර වලට මැදිහත් වේ.', 'ඇඩ්‍රිනලින් - දීර්ඝකාලීන ආතති ප්‍රතිචාර වලට මැදිහත් වේ.', NULL, 'sanitized', 'v1', 0, 1);
