INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e9fb8ae-6987-4ad2-99a9-c0777e8c2b32', '994353db-6ca4-532e-b3c3-8ca1d7c43335', 'මෙලටොනින් - සහජ ප්‍රතිශක්තිය යාමනය කරයි.', 'මෙලටොනින් - සහජ ප්‍රතිශක්තිය යාමනය කරයි.', NULL, 'sanitized', 'v1', 2, 0);
