INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('54cb0ab5-fd49-4cf4-b7a8-27a398b02628', 'e794ae2e-f3b3-5753-a1cc-416c978e5323', 'භ්‍රෑණයේ විකසනය වන ගොනැඩවල මූලික ජන්මාණු සෛලවල ප්‍රභවය ලෙස ක්‍රියා කරයි.', 'භ්‍රෑණයේ විකසනය වන ගොනැඩවල මූලික ජන්මාණු සෛලවල ප්‍රභවය ලෙස ක්‍රියා කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1d5d5bb1-e3fa-5dd5-89f2-00ca1a66e817', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 29, '<p>උපතින් පසු මිනිස් කශේරුවේ පූර්වට උත්තල වක්‍ර විකසනය වන්නේ</p>', '<p>උපතින් පසු මිනිස් කශේරුවේ පූර්වට උත්තල වක්‍ර විකසනය වන්නේ</p>', NULL, 'මිනිස් කශේරුවේ ප්‍රාථමික වක්‍ර (උරස් සහ ත්‍රිකාස්ථික) පූර්වට අවතල (concave) වේ. උපතින් පසු ළදරුවා හිස එසවීමත් සමග ග්‍රෛවී ප්‍රදේශයේ ද, ඇවිදීමට පටන් ගැනීමත් සමග කටී ප්‍රදේශයේ ද පූර්වට උත්තල (convex) වූ ද්විතියික වක්‍ර විකසනය වේ.', 'මිනිස් කශේරුවේ ප්‍රාථමික වක්‍ර (උරස් සහ ත්‍රිකාස්ථික) පූර්වට අවතල (concave) වේ. උපතින් පසු ළදරුවා හිස එසවීමත් සමග ග්‍රෛවී ප්‍රදේශයේ ද, ඇවිදීමට පටන් ගැනීමත් සමග කටී ප්‍රදේශයේ ද පූර්වට උත්තල (convex) වූ ද්විතියික වක්‍ර විකසනය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
