INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ceef1f71-99f7-4298-bf75-1833c08c2696', '1d5d5bb1-e3fa-5dd5-89f2-00ca1a66e817', 'ග්‍රෛවී සහ කටී ප්‍රදේශ වලය.', 'ග්‍රෛවී සහ කටී ප්‍රදේශ වලය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b32334ad-454b-4f30-9823-26371a4ff22e', '1d5d5bb1-e3fa-5dd5-89f2-00ca1a66e817', 'ග්‍රෛවී සහ ත්‍රිකාස්ථික ප්‍රදේශ වලය.', 'ග්‍රෛවී සහ ත්‍රිකාස්ථික ප්‍රදේශ වලය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5f36a8bb-e3d0-4684-9d54-971f17068643', '1d5d5bb1-e3fa-5dd5-89f2-00ca1a66e817', 'කටී සහ ත්‍රිකාස්ථික ප්‍රදේශවල ය.', 'කටී සහ ත්‍රිකාස්ථික ප්‍රදේශවල ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fceb7f25-2c45-50c3-b018-923e554f8e33', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 30, '<p>මානව සැකිල්ල පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මානව සැකිල්ල පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'දණිස් කටුව (Patella) යනු ඌර්වස්ථියේ (Femur) විදුර කෙළවර (Distal end) සමග සන්ධානය වී දණිස් සන්ධියට සම්බන්ධ වන සෙසමොයිඩ් අස්ථියකි.<br><br>හිස උස් පහත් කිරීමට දායක වන්නේ ඇට්ලස් කශේරුකාවයි. අස්ථි ඝනත්වය අඩු වීම ඔස්ටියෝපොරෝසිස් රෝගයයි. හිස්කබලේ ඇති එකම චලනය කළ හැකි අස්ථිය අධෝහනුවයි (ඌර්ධවහනුව නොවේ).', 'දණිස් කටුව (Patella) යනු ඌර්වස්ථියේ (Femur) විදුර කෙළවර (Distal end) සමග සන්ධානය වී දණිස් සන්ධියට සම්බන්ධ වන සෙසමොයිඩ් අස්ථියකි.<br><br>හිස උස් පහත් කිරීමට දායක වන්නේ ඇට්ලස් කශේරුකාවයි. අස්ථි ඝනත්වය අඩු වීම ඔස්ටියෝපොරෝසිස් රෝගයයි. හිස්කබලේ ඇති එකම චලනය කළ හැකි අස්ථිය අධෝහනුවයි (ඌර්ධවහනුව නොවේ).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('29617535-1fac-4e0c-a1b1-935b68da8dfa', 'fceb7f25-2c45-50c3-b018-923e554f8e33', 'ආක්ෂක කශේරුකාව අපරකපාල අස්ථිය සමග සන්ධානය වීම හිස උස් පහත් කිරීමේ චලනයන්ට ඉඩ සලසයි.', 'ආක්ෂක කශේරුකාව අපරකපාල අස්ථිය සමග සන්ධානය වීම හිස උස් පහත් කිරීමේ චලනයන්ට ඉඩ සලසයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9b27026a-cf98-4de5-997f-20e5cd35671c', 'fceb7f25-2c45-50c3-b018-923e554f8e33', 'පූර්ව ගාත්‍රයේ සියලුම හස්තකූර්වාස්ථි මැණික්කටු සන්ධිය සෑදීමට දායක වේ.', 'පූර්ව ගාත්‍රයේ සියලුම හස්තකූර්වාස්ථි මැණික්කටු සන්ධිය සෑදීමට දායක වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0ec1a909-7b52-44ae-a175-afe1c7e5867a', 'fceb7f25-2c45-50c3-b018-923e554f8e33', 'ඔස්ටියෝ ආතරයිටිස් යනු අස්ථිවල ඝනත්වය අඩු වීම හා සම්බන්ධ තත්ත්වයකි.', 'ඔස්ටියෝ ආතරයිටිස් යනු අස්ථිවල ඝනත්වය අඩු වීම හා සම්බන්ධ තත්ත්වයකි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('820d951e-5884-4779-9c2c-89a70da02c32', 'fceb7f25-2c45-50c3-b018-923e554f8e33', 'දණිස් කටුව ඌර්වස්ථියේ විදුර කෙළවර සමඟ සන්ධානය වේ.', 'දණිස් කටුව ඌර්වස්ථියේ විදුර කෙළවර සමඟ සන්ධානය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d0cef13d-a831-4d7b-9258-4e93daa96a50', 'fceb7f25-2c45-50c3-b018-923e554f8e33', 'හිස්කබලේ ඇති චලනය කළ හැකි එක ම අස්ථිය ඌර්ධවහනුක අස්ථියයි.', 'හිස්කබලේ ඇති චලනය කළ හැකි එක ම අස්ථිය ඌර්ධවහනුක අස්ථියයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ff32ac9f-f60b-5ab8-b03e-a0a9a3367d34', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 31, '<p>එක්තරා විශේෂයක ඇතැම් ශාක දම් පැහැති පුෂ්ප දරන අතර එම විශේෂයේ අනික් ශාක සුදු පැහැති පුෂ්ප දරයි.<br><br>මෙම ශාක විශේෂයේ මල්වල පැහැයේ ආවේණිය පැහැදිලි කිරීම සඳහා</p>', '<p>එක්තරා විශේෂයක ඇතැම් ශාක දම් පැහැති පුෂ්ප දරන අතර එම විශේෂයේ අනික් ශාක සුදු පැහැති පුෂ්ප දරයි.<br><br>මෙම ශාක විශේෂයේ මල්වල පැහැයේ ආවේණිය පැහැදිලි කිරීම සඳහා</p>', NULL, 'මල්වල පැහැය යනු එක් ලක්ෂණයක් (Single trait) පමණි. එක් ලක්ෂණයක ආවේණිය හැදෑරීම සඳහා සහ එය පැහැදිලි කිරීම සඳහා ඒකාංග මුහුමක් (Monohybrid cross) ප්‍රමාණවත් වේ.', 'මල්වල පැහැය යනු එක් ලක්ෂණයක් (Single trait) පමණි. එක් ලක්ෂණයක ආවේණිය හැදෑරීම සඳහා සහ එය පැහැදිලි කිරීම සඳහා ඒකාංග මුහුමක් (Monohybrid cross) ප්‍රමාණවත් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
