INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c132a36f-d0e3-4239-96a3-41972599fcc0', 'ff32ac9f-f60b-5ab8-b03e-a0a9a3367d34', 'අසම්පූර්ණ ප්‍රමුඛතාව පිළිබඳ දැනුම අවශ්‍යය.', 'අසම්පූර්ණ ප්‍රමුඛතාව පිළිබඳ දැනුම අවශ්‍යය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('253d7371-0ef0-42fc-be36-ec558e07e210', 'ff32ac9f-f60b-5ab8-b03e-a0a9a3367d34', 'ජාන ප්‍රතිබද්ධය පිළිබඳ දැනුම අවශ්‍ය ය.', 'ජාන ප්‍රතිබද්ධය පිළිබඳ දැනුම අවශ්‍ය ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7aac2be9-673b-579b-86fe-0e9ac77616ac', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 32, '<p>සුන්‍යෂ්ටිකයන්ගේ වර්ණ දේහවල ඇති නිර්කේත අනුක්‍රම සහ හඳුනාගත හැකි කෘත්‍යයක් නොමැති DNA ඛණ්ඩ පිළිවෙළින්</p>', '<p>සුන්‍යෂ්ටිකයන්ගේ වර්ණ දේහවල ඇති නිර්කේත අනුක්‍රම සහ හඳුනාගත හැකි කෘත්‍යයක් නොමැති DNA ඛණ්ඩ පිළිවෙළින්</p>', NULL, 'ජානයක් තුළ පවතින ප්‍රෝටීන සඳහා කේතනය නොකරන (non-coding) අනුක්‍රම ඉන්ට්‍රෝන (Introns) ලෙස හඳුන්වයි. ජාන දෙකක් අතර පවතින, හඳුනාගත හැකි කෘත්‍යයක් නොමැති $DNA$ ඛණ්ඩ අන්තර්ජාන $DNA$ (Intergenic DNA) ලෙස හැඳින්වේ.', 'ජානයක් තුළ පවතින ප්‍රෝටීන සඳහා කේතනය නොකරන (non-coding) අනුක්‍රම ඉන්ට්‍රෝන (Introns) ලෙස හඳුන්වයි. ජාන දෙකක් අතර පවතින, හඳුනාගත හැකි කෘත්‍යයක් නොමැති $DNA$ ඛණ්ඩ අන්තර්ජාන $DNA$ (Intergenic DNA) ලෙස හැඳින්වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
