INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bca643cd-c841-4296-b619-99437ad68a5a', '7aac2be9-673b-579b-86fe-0e9ac77616ac', 'ඉයුක්‍රොමටින් සහ අන්තර්ජාන DNA වේ.', 'ඉයුක්‍රොමටින් සහ අන්තර්ජාන DNA වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cd0083e8-13b4-5063-9090-4ca1d0ec4f28', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 33, '<p>පොලිපෙප්ටයිඩ සංශ්ලේෂණය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>පොලිපෙප්ටයිඩ සංශ්ලේෂණය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'පරිවර්තනයේදී $mRNA$ අණුවක පවතින ආරම්භක කෝඩෝනය (Start codon) වන්නේ $AUG$ ය. එමගින් සෑමවිටම මෙතියොනීන් (Methionine) නම් ඇමිනෝ අම්ලය සඳහා කේතය සපයයි. (කෝඩෝන 64න් 61ක් ඇමිනෝ අම්ල සඳහා කේත සපයන අතර ඉතිරි 3 නතර කිරීමේ කෝඩෝන වේ).', 'පරිවර්තනයේදී $mRNA$ අණුවක පවතින ආරම්භක කෝඩෝනය (Start codon) වන්නේ $AUG$ ය. එමගින් සෑමවිටම මෙතියොනීන් (Methionine) නම් ඇමිනෝ අම්ලය සඳහා කේතය සපයයි. (කෝඩෝන 64න් 61ක් ඇමිනෝ අම්ල සඳහා කේත සපයන අතර ඉතිරි 3 නතර කිරීමේ කෝඩෝන වේ).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('09474f30-4611-480c-b98d-b252b6334cc5', 'cd0083e8-13b4-5063-9090-4ca1d0ec4f28', 'DNA වල T වෙනුවට mRNA වල U තිබීම හැර DNA අච්චු දාමයේ සහ එහි mRNA අණුවේ භෂ්ම අනුපිළිවෙළ සමාන වේ.', 'DNA වල T වෙනුවට mRNA වල U තිබීම හැර DNA අච්චු දාමයේ සහ එහි mRNA අණුවේ භෂ්ම අනුපිළිවෙළ සමාන වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('06c2557b-d47d-4005-a253-73658930eee0', 'cd0083e8-13b4-5063-9090-4ca1d0ec4f28', 'ප්‍රාග්න්‍යෂ්ටිකයකුගේ mRNA අණුවකට සුන්‍යෂ්ටිකයෙකු තුළ පොලිපෙප්ටයිඩයක් කේතනය කළ නොහැකි ය.', 'ප්‍රාග්න්‍යෂ්ටිකයකුගේ mRNA අණුවකට සුන්‍යෂ්ටිකයෙකු තුළ පොලිපෙප්ටයිඩයක් කේතනය කළ නොහැකි ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5f5bc156-d38d-4b19-a9a9-b590d494b873', 'cd0083e8-13b4-5063-9090-4ca1d0ec4f28', 'mRNA අණුවක ආරම්භක කෝඩෝනය AUG වන අතර එය මෙතියොනීන් සඳහා කේතය සපයයි.', 'mRNA අණුවක ආරම්භක කෝඩෝනය AUG වන අතර එය මෙතියොනීන් සඳහා කේතය සපයයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a7ee8646-5c79-4537-9f74-8b8a7167c8ca', 'cd0083e8-13b4-5063-9090-4ca1d0ec4f28', 'කෝඩෝන 64 ක් ඇති අතර ඒවායින් 62 ක් ඇමිනෝ අම්ල සඳහා කේත සපයයි.', 'කෝඩෝන 64 ක් ඇති අතර ඒවායින් 62 ක් ඇමිනෝ අම්ල සඳහා කේත සපයයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4df576fb-a0af-4b93-91da-912c85a684d0', 'cd0083e8-13b4-5063-9090-4ca1d0ec4f28', 'tRNA අණුවක ප්‍රථම භෂ්ම ත්‍රිත්වය AUGය.', 'tRNA අණුවක ප්‍රථම භෂ්ම ත්‍රිත්වය AUGය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('90e2f803-8131-5afa-9e0f-d590548c1236', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 34, '<p>සීමා සිතියම් වඩාත් ම වැදගත් වන්නේ</p>', '<p>සීමා සිතියම් වඩාත් ම වැදගත් වන්නේ</p>', NULL, 'සීමා සිතියම් (Restriction maps) මගින් $DNA$ අණුවක විවිධ සීමා එන්සයිම වලට අදාළ කැපුම් ස්ථාන පිහිටන අනුපිළිවෙළ පෙන්වයි. මේවා ප්‍රත්‍යාවර්ත $DNA$ තාක්ෂණයේදී ප්ලාස්මිඩ වැනි ක්ලෝනකරණ වාහකයින් (Cloning vectors) ගොඩනැගීමට සහ විශ්ලේෂණය කිරීමට බෙහෙවින් වැදගත් වේ.', 'සීමා සිතියම් (Restriction maps) මගින් $DNA$ අණුවක විවිධ සීමා එන්සයිම වලට අදාළ කැපුම් ස්ථාන පිහිටන අනුපිළිවෙළ පෙන්වයි. මේවා ප්‍රත්‍යාවර්ත $DNA$ තාක්ෂණයේදී ප්ලාස්මිඩ වැනි ක්ලෝනකරණ වාහකයින් (Cloning vectors) ගොඩනැගීමට සහ විශ්ලේෂණය කිරීමට බෙහෙවින් වැදගත් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('50643034-4ff2-4688-ba44-8342c54f081d', '90e2f803-8131-5afa-9e0f-d590548c1236', 'ජිනෝමයක් තුළ ජානවල බහු පිටපත් හඳුනා ගැනීමේදී ය.', 'ජිනෝමයක් තුළ ජානවල බහු පිටපත් හඳුනා ගැනීමේදී ය.', NULL, 'sanitized', 'v1', 0, 1);
