INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('834fa396-667e-4fde-994c-d723068ca464', '90e2f803-8131-5afa-9e0f-d590548c1236', 'ක්ලෝනකරණ වාහකයින් ගොඩ නැගීමේදී ය.', 'ක්ලෝනකරණ වාහකයින් ගොඩ නැගීමේදී ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('26f3ecd0-0bbc-48de-97e9-6ab29ce7276d', '90e2f803-8131-5afa-9e0f-d590548c1236', 'පිළිකා රෝග විනිශ්චයේදී ය.', 'පිළිකා රෝග විනිශ්චයේදී ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('019f8017-274f-4975-a96a-7bbaa5cd7237', '90e2f803-8131-5afa-9e0f-d590548c1236', 'පීතෘත්වය පරීක්ෂා කිරීමේදී ය.', 'පීතෘත්වය පරීක්ෂා කිරීමේදී ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d302ed0b-9bbb-595a-aefc-f9a528377603', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 35, '<p>තුන්ද්‍රාවල ජීවත්වන සතුන් තිදෙනෙකු වන්නේ</p>', '<p>තුන්ද්‍රාවල ජීවත්වන සතුන් තිදෙනෙකු වන්නේ</p>', NULL, 'තුන්ද්‍රා (Tundra) බියෝමයේ අධික ශීත කාලගුණයට ඔරොත්තු දිය හැකි සතුන් ජීවත් වේ. කැරිබු (Caribou), වෘකයා (Wolf), වලසා (Bear), Musk oxen, ආක්ටික් නරියා යනාදිය මීට උදාහරණ වේ.', 'තුන්ද්‍රා (Tundra) බියෝමයේ අධික ශීත කාලගුණයට ඔරොත්තු දිය හැකි සතුන් ජීවත් වේ. කැරිබු (Caribou), වෘකයා (Wolf), වලසා (Bear), Musk oxen, ආක්ටික් නරියා යනාදිය මීට උදාහරණ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
