INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b49b5806-5343-4293-a498-bde88022e73d', 'd302ed0b-9bbb-595a-aefc-f9a528377603', 'පිනිමුවා, සයිබීරියානු කොටියා සහ වලසාය.', 'පිනිමුවා, සයිබීරියානු කොටියා සහ වලසාය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4009cbb7-1a8f-435d-89f0-84f396b5b5da', 'd302ed0b-9bbb-595a-aefc-f9a528377603', 'Musk oxen, නරියා සහ උතුරු ඇමෙරිකානු ගෝනාය.', 'Musk oxen, නරියා සහ උතුරු ඇමෙරිකානු ගෝනාය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ba3bba2f-52bf-5e75-9d93-2609aa04fff1', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 36, '<p>අවශිෂ්ට විශේෂයක් සහ ශ්‍රී ලංකාවට ඒක දේශික විශේෂයක් පිළිවෙළින් දක්වන ප්‍රතිචාරය තෝරන්න.</p>', '<p>අවශිෂ්ට විශේෂයක් සහ ශ්‍රී ලංකාවට ඒක දේශික විශේෂයක් පිළිවෙළින් දක්වන ප්‍රතිචාරය තෝරන්න.</p>', NULL, 'අතීතයේ බහුලව පැවතී දැනට සීමිතව පවතින ජීවමාන ෆොසිලයක් හෙවත් අවශිෂ්ට විශේෂයක් (Relict species) සඳහා හොඳම උදාහරණයක් ලෙස $Lingula \ sp.$ දැක්විය හැක. $Loris \ tardigradus$ (ශ්‍රී ලංකා රතු උණහපුලුවා) යනු ශ්‍රී ලංකාවට පමණක් ආවේණික (Endemic/ඒකදේශික) විශේෂයකි.', 'අතීතයේ බහුලව පැවතී දැනට සීමිතව පවතින ජීවමාන ෆොසිලයක් හෙවත් අවශිෂ්ට විශේෂයක් (Relict species) සඳහා හොඳම උදාහරණයක් ලෙස $Lingula \ sp.$ දැක්විය හැක. $Loris \ tardigradus$ (ශ්‍රී ලංකා රතු උණහපුලුවා) යනු ශ්‍රී ලංකාවට පමණක් ආවේණික (Endemic/ඒකදේශික) විශේෂයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
