INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c8cc3182-68dd-4fc7-998c-83bec5623992', '5d1d766e-8871-50df-a27c-2e9c615d15b4', 'සල්ෆර් ඩයොක්සයිඩ්, හයිඩ්‍රොෆ්ලුවරෝකාබන් සහ මීතයිල් බ්‍රෝමයිඩ් (MeBr) ය.', 'සල්ෆර් ඩයොක්සයිඩ්, හයිඩ්‍රොෆ්ලුවරෝකාබන් සහ මීතයිල් බ්‍රෝමයිඩ් (MeBr) ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e9c94d42-22cd-40d3-94e3-f121d18c4619', '5d1d766e-8871-50df-a27c-2e9c615d15b4', 'නයිට්‍රස් ඔක්සයිඩ්, මීතේන් සහ කාබන් මොනොක්සයිඩ් ය.', 'නයිට්‍රස් ඔක්සයිඩ්, මීතේන් සහ කාබන් මොනොක්සයිඩ් ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5467666e-2bfa-413f-ae85-765ab65dbb43', '5d1d766e-8871-50df-a27c-2e9c615d15b4', 'නයිට්‍රික් ඔක්සයිඩ්, හීලින් සහ ක්ලෝරෝෆ්ලුවරෝකාබන්ය.', 'නයිට්‍රික් ඔක්සයිඩ්, හීලින් සහ ක්ලෝරෝෆ්ලුවරෝකාබන්ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7fd9c6a5-c2b8-4a75-b5fc-d2c3897f969b', '5d1d766e-8871-50df-a27c-2e9c615d15b4', 'නයිට්‍රජන් ඩයොක්සයිඩ්, සල්ෆර් හෙක්සෆ්ලෝරයිඩ් සහ මීතේන් ය.', 'නයිට්‍රජන් ඩයොක්සයිඩ්, සල්ෆර් හෙක්සෆ්ලෝරයිඩ් සහ මීතේන් ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('084958cf-7e99-5eba-ba10-ae5c6039f9e2', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 38, '<p>බැක්ටීරියා තුළ DNA/RNA සංශ්ලේෂණය වීම නිශේධනය කරන්නේ පහත සඳහන් කුමන ප්‍රතිජීවකය ද ?</p>', '<p>බැක්ටීරියා තුළ DNA/RNA සංශ්ලේෂණය වීම නිශේධනය කරන්නේ පහත සඳහන් කුමන ප්‍රතිජීවකය ද ?</p>', NULL, 'රිෆැම්පින් (Rifampin / Rifampicin) ප්‍රතිජීවකය බැක්ටීරියා $RNA$ පොලිමරේස් එන්සයිමය සමඟ බැඳෙමින් $RNA$ සංශ්ලේෂණය (පිටපත් කිරීම) නිශේධනය කරයි. පෙනිසිලින් සෛල බිත්ති සංශ්ලේෂණයට ද, එරිත්‍රොමයිසින් හා ටෙට්‍රාසයික්ලින් රයිබොසෝම හරහා ප්‍රෝටීන සංශ්ලේෂණයට ද බාධා පමුණුවයි.', 'රිෆැම්පින් (Rifampin / Rifampicin) ප්‍රතිජීවකය බැක්ටීරියා $RNA$ පොලිමරේස් එන්සයිමය සමඟ බැඳෙමින් $RNA$ සංශ්ලේෂණය (පිටපත් කිරීම) නිශේධනය කරයි. පෙනිසිලින් සෛල බිත්ති සංශ්ලේෂණයට ද, එරිත්‍රොමයිසින් හා ටෙට්‍රාසයික්ලින් රයිබොසෝම හරහා ප්‍රෝටීන සංශ්ලේෂණයට ද බාධා පමුණුවයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
