INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1749e636-0ad3-5193-8c93-bd73d3bdc98d', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 39, '<p>ක්ෂුද්‍රජීවීන් පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ක්ෂුද්‍රජීවීන් පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'මූල ගෝලයේ (Rhizosphere) වෙසෙන ව්‍යාධිජනක දිලීර (Pathogenic fungi) තම පෝෂණ ද්‍රව්‍ය ප්‍රධාන වශයෙන්ම ලබා ගන්නේ ශාක මුල් මගින් පසට ශ්‍රාවය කරන/නිර්යාස කරන (Root exudates) සංයෝග (උදා: සීනි, ඇමිනෝ අම්ල) වලිනි.', 'මූල ගෝලයේ (Rhizosphere) වෙසෙන ව්‍යාධිජනක දිලීර (Pathogenic fungi) තම පෝෂණ ද්‍රව්‍ය ප්‍රධාන වශයෙන්ම ලබා ගන්නේ ශාක මුල් මගින් පසට ශ්‍රාවය කරන/නිර්යාස කරන (Root exudates) සංයෝග (උදා: සීනි, ඇමිනෝ අම්ල) වලිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e65e364f-716f-469e-8a3e-5a3a993d3ac0', '1749e636-0ad3-5193-8c93-bd73d3bdc98d', 'මූල ගෝලයක සිටින ව්‍යාධිජනක දිලීර පෝෂණ ද්‍රව්‍ය ලබාගන්නේ ශාක මුල් මගින් නිර්යාස කරනු ලබන සංයෝග වලිනි.', 'මූල ගෝලයක සිටින ව්‍යාධිජනක දිලීර පෝෂණ ද්‍රව්‍ය ලබාගන්නේ ශාක මුල් මගින් නිර්යාස කරනු ලබන සංයෝග වලිනි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3f2e85de-f652-43be-a543-46fa26b0fa65', '1749e636-0ad3-5193-8c93-bd73d3bdc98d', 'පාංශු ද්‍රාවණයට පොස්පොරස් මුදා හැරීම සඳහා දායක වන ක්ෂාරීය සංයෝග සමහර බැක්ටීරියා මගින් ස්‍රාවය කරනු ලැබේ.', 'පාංශු ද්‍රාවණයට පොස්පොරස් මුදා හැරීම සඳහා දායක වන ක්ෂාරීය සංයෝග සමහර බැක්ටීරියා මගින් ස්‍රාවය කරනු ලැබේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b2220411-00fb-4e88-b8b6-0849d3659f99', '1749e636-0ad3-5193-8c93-bd73d3bdc98d', 'ඇක්ටිනොමයිසිටීස්, නිර්වායු තත්ත්ව යටතේදී වඩාත් කාර්යක්ෂමව කොම්පෝස්ට් සාදයි.', 'ඇක්ටිනොමයිසිටීස්, නිර්වායු තත්ත්ව යටතේදී වඩාත් කාර්යක්ෂමව කොම්පෝස්ට් සාදයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cc3b0b53-ea8e-4ebd-b801-dcd3df3c34d1', '1749e636-0ad3-5193-8c93-bd73d3bdc98d', 'රයිසෝබියා, රනිල ශාක සහ Azolla යන දෙකම සමඟ සහජීවී සම්බන්ධතා ඇති කර ගනී.', 'රයිසෝබියා, රනිල ශාක සහ Azolla යන දෙකම සමඟ සහජීවී සම්බන්ධතා ඇති කර ගනී.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5f479baf-1db8-4d93-bb8d-224f68bd7896', '1749e636-0ad3-5193-8c93-bd73d3bdc98d', 'Azotobacter spp. වලට විටමින් C නිපදවිය හැකි ය.', 'Azotobacter spp. වලට විටමින් C නිපදවිය හැකි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f2bbadb5-804c-581d-a9a8-4c957711834f', 'c02f39c8-7983-5bca-8108-b3c0d508ed8e', 40, '<p>කාර්මික අපජලය පිරිසිදු කිරීමේ ප්‍රාථමික පිරියම් කිරීමේ පියවරක් වන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', '<p>කාර්මික අපජලය පිරිසිදු කිරීමේ ප්‍රාථමික පිරියම් කිරීමේ පියවරක් වන්නේ පහත සඳහන් ඒවායින් කුමක්ද?</p>', NULL, 'අපජල පිරිපහදුවේ ප්‍රාථමික පිරියම් කිරීමේදී (Primary treatment) සිදු කරන්නේ මූලිකවම භෞතික ක්‍රම යොදාගෙන පාවෙන ඝන ද්‍රව්‍ය, තෙල් සහ ග්‍රීස් වැනි දෑ ඉවත් කිරීමයි. යාන්ත්‍රික වාතනය සහ පාෂාණමය ද්‍රව්‍ය මත ඉසීම (Trickling filters) ද්විතීයික පිරියම් කිරීමට (Secondary treatment) අයත් වේ.', 'අපජල පිරිපහදුවේ ප්‍රාථමික පිරියම් කිරීමේදී (Primary treatment) සිදු කරන්නේ මූලිකවම භෞතික ක්‍රම යොදාගෙන පාවෙන ඝන ද්‍රව්‍ය, තෙල් සහ ග්‍රීස් වැනි දෑ ඉවත් කිරීමයි. යාන්ත්‍රික වාතනය සහ පාෂාණමය ද්‍රව්‍ය මත ඉසීම (Trickling filters) ද්විතීයික පිරියම් කිරීමට (Secondary treatment) අයත් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
