INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('33683a79-4909-56db-8b7e-071bd20f9f63', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 1, '<p>Urea which is an excretory product is produced in</p>', '<p>Urea which is an excretory product is produced in</p>', NULL, 'Urea is produced in the liver through the ornithine cycle and is transported via blood to the kidneys for excretion.', 'Urea is produced in the liver through the ornithine cycle and is transported via blood to the kidneys for excretion.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
