INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('67815ef3-134f-5d0a-973b-3121b2a35547', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 2, '<p>What is the unit of power?</p>', '<p>What is the unit of power?</p>', NULL, 'Power is the rate of doing work or transferring energy. Since $P = \frac{W}{t}$, its standard unit is Joules per second ($J s^{-1}$), which is equivalent to Watts ($W$).', 'Power is the rate of doing work or transferring energy. Since $P = \frac{W}{t}$, its standard unit is Joules per second ($J s^{-1}$), which is equivalent to Watts ($W$).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
