INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f6b4c28e-599a-5b21-a0d7-f55c37f9c800', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 3, '<p>The formula of an isopropyl alcohol molecule is $(CH_{3})_{2}CHOH$. What is the number of atoms in this molecule?</p>', '<p>The formula of an isopropyl alcohol molecule is $(CH_{3})_{2}CHOH$. What is the number of atoms in this molecule?</p>', NULL, 'Let''s count the atoms in the formula $(CH_3)_2CHOH$.<br>Carbon ($C$) atoms: $2 \times 1 + 1 = 3$.<br>Hydrogen ($H$) atoms: $2 \times 3 + 1 + 1 = 8$.<br>Oxygen ($O$) atoms: $1$.<br>Total number of atoms = $3 + 8 + 1 = 12$.', 'Let''s count the atoms in the formula $(CH_3)_2CHOH$.<br>Carbon ($C$) atoms: $2 \times 1 + 1 = 3$.<br>Hydrogen ($H$) atoms: $2 \times 3 + 1 + 1 = 8$.<br>Oxygen ($O$) atoms: $1$.<br>Total number of atoms = $3 + 8 + 1 = 12$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
