INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c97b5754-d9a7-5749-8960-a8b2734bf960', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 5, '<p>When two objects are rubbed together and one of them gets positively charged, transferred to the other are</p>', '<p>When two objects are rubbed together and one of them gets positively charged, transferred to the other are</p>', NULL, 'Protons and neutrons are tightly bound within the nucleus of an atom. Only electrons are loosely bound and can be transferred through friction. When an object loses electrons, it becomes positively charged.', 'Protons and neutrons are tightly bound within the nucleus of an atom. Only electrons are loosely bound and can be transferred through friction. When an object loses electrons, it becomes positively charged.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
