INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('03fd7751-01ad-5e5b-afa1-60492a86a52b', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 13, '<p>What is the cathodic reaction taking place in the above cell?</p>', '<p>What is the cathodic reaction taking place in the above cell?</p>', NULL, 'At the copper cathode in a simple cell containing dilute sulphuric acid, hydrogen ions ($H^+$) from the acid accept the incoming electrons and are reduced to form hydrogen gas bubbles ($H_2$).', 'At the copper cathode in a simple cell containing dilute sulphuric acid, hydrogen ions ($H^+$) from the acid accept the incoming electrons and are reduced to form hydrogen gas bubbles ($H_2$).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
