INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a18a3e48-8005-575a-b87a-ac8629122434', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 14, '<p>Consider the following statements regarding refraction of light.<br><br>A - Light refracts only when it travels from a rarer medium to a denser medium.<br>B - Reason for the refraction is the difference in the speed of light in the two media.<br>C - Frequency of light changes during refraction.<br><br>Of the above, true statement(s) is/are</p>', '<p>Consider the following statements regarding refraction of light.<br><br>A - Light refracts only when it travels from a rarer medium to a denser medium.<br>B - Reason for the refraction is the difference in the speed of light in the two media.<br>C - Frequency of light changes during refraction.<br><br>Of the above, true statement(s) is/are</p>', NULL, 'Refraction is defined as the bending of light as it passes between any two media with different optical densities, due to the change in the speed of light. Light can refract from rarer to denser, and denser to rarer. The frequency of light never changes during refraction.', 'Refraction is defined as the bending of light as it passes between any two media with different optical densities, due to the change in the speed of light. Light can refract from rarer to denser, and denser to rarer. The frequency of light never changes during refraction.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
