INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('acc2f0b0-1b39-5339-a3bf-04dd4c591e9a', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 15, '<p>The acceleration due to gravity on the Earth is $10 m s^{-2}$. On the moon its value is $\frac{1}{6}$ th the value on the Earth. What is the weight of an object on the moon if it weighs 60 N on the Earth?</p>', '<p>The acceleration due to gravity on the Earth is $10 m s^{-2}$. On the moon its value is $\frac{1}{6}$ th the value on the Earth. What is the weight of an object on the moon if it weighs 60 N on the Earth?</p>', NULL, 'Weight is directly proportional to gravitational acceleration ($W = mg$). Since the object''s mass is constant, its weight on the moon is simply $\frac{1}{6}$ of its weight on Earth. $\frac{60 N}{6} = 10 N$.', 'Weight is directly proportional to gravitational acceleration ($W = mg$). Since the object''s mass is constant, its weight on the moon is simply $\frac{1}{6}$ of its weight on Earth. $\frac{60 N}{6} = 10 N$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
