INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dfdf4820-f40f-5a19-9874-ce959c0f677c', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 16, '<p>Of the following characteristics, what are the characteristics common only to Aves and Mammalia belonging to the vertebrate animal group?<br><br>A - warm bloodedness<br>B - skin covered with hair<br>C - bony internal skeleton<br>D - four chambered heart</p>', '<p>Of the following characteristics, what are the characteristics common only to Aves and Mammalia belonging to the vertebrate animal group?<br><br>A - warm bloodedness<br>B - skin covered with hair<br>C - bony internal skeleton<br>D - four chambered heart</p>', NULL, 'Both Aves (birds) and Mammalia are homeothermic (warm-blooded) and uniquely share a completely separated four-chambered heart. Hair is a trait exclusive to mammals, and bony skeletons are found in other groups such as Osteichthyes.', 'Both Aves (birds) and Mammalia are homeothermic (warm-blooded) and uniquely share a completely separated four-chambered heart. Hair is a trait exclusive to mammals, and bony skeletons are found in other groups such as Osteichthyes.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
