INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5188d1fd-c4ac-584c-9f8d-a7f248b9672a', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 18, '<p>When a few drops of methyl orange were added to a certain solution, it turned red. Which of the following is most likely to be the pH value of that solution?</p>', '<p>When a few drops of methyl orange were added to a certain solution, it turned red. Which of the following is most likely to be the pH value of that solution?</p>', NULL, 'Methyl orange is a pH indicator that is red in strongly acidic solutions (pH less than 3.1) and turns yellow in neutral and basic environments. Therefore, a pH of 2 is the only logical answer.', 'Methyl orange is a pH indicator that is red in strongly acidic solutions (pH less than 3.1) and turns yellow in neutral and basic environments. Therefore, a pH of 2 is the only logical answer.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
