INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2a74c3ed-ec28-515a-a50f-e4b863c853d8', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 19, '<p>It takes four seconds for an ultrasonic wave sent by a ship to the bottom of the sea to be reflected and come back to the ship. If the depth to the bottom of the sea is 2880 m, what is the speed of the ultrasonic wave in sea water?</p>', '<p>It takes four seconds for an ultrasonic wave sent by a ship to the bottom of the sea to be reflected and come back to the ship. If the depth to the bottom of the sea is 2880 m, what is the speed of the ultrasonic wave in sea water?</p>', NULL, 'The wave travels down to the sea floor and back up, so the total distance $d = 2 \times 2880 m = 5760 m$. The time taken $t = 4 s$. Speed $v = \frac{d}{t} = \frac{5760}{4} = 1440 m s^{-1}$.', 'The wave travels down to the sea floor and back up, so the total distance $d = 2 \times 2880 m = 5760 m$. The time taken $t = 4 s$. Speed $v = \frac{d}{t} = \frac{5760}{4} = 1440 m s^{-1}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
