INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a029054d-94db-5abd-8a12-494b405436e4', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 20, '<p>Given below are some properties of a gas.<br><br>- can be burnt easily<br>- density is less than that of air<br>- slightly soluble in water<br><br>This gas is</p>', '<p>Given below are some properties of a gas.<br><br>- can be burnt easily<br>- density is less than that of air<br>- slightly soluble in water<br><br>This gas is</p>', NULL, 'Hydrogen gas ($H_2$) matches all these properties: it is highly combustible, it is the lightest gas (making it much less dense than air), and it has very low solubility in water.', 'Hydrogen gas ($H_2$) matches all these properties: it is highly combustible, it is the lightest gas (making it much less dense than air), and it has very low solubility in water.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
