INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('505f9a9b-6869-5680-ac71-3dab4cad7efd', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 21, '<p>What is the part belonging to the central nervous system which controls the rate of heart beat?</p>', '<p>What is the part belonging to the central nervous system which controls the rate of heart beat?</p>', NULL, 'The medulla oblongata forms the lowest part of the brainstem and contains vital autonomic control centers, including the cardiac center that regulates involuntary functions like heart rate and breathing.', 'The medulla oblongata forms the lowest part of the brainstem and contains vital autonomic control centers, including the cardiac center that regulates involuntary functions like heart rate and breathing.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
