INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e628fd68-c0ab-5c35-96a5-f0114e4091bc', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 22, '<p>Consider the following statements about the resistance of a conductor.<br><br>A - depends on the potential difference between the two ends of the conductor<br>B - directly proportional to the length of the conductor<br>C - depends on the current flowing through the conductor<br><br>Of the above, the true statement(s) is/are,</p>', '<p>Consider the following statements about the resistance of a conductor.<br><br>A - depends on the potential difference between the two ends of the conductor<br>B - directly proportional to the length of the conductor<br>C - depends on the current flowing through the conductor<br><br>Of the above, the true statement(s) is/are,</p>', NULL, 'The resistance of a given conductor relies on its length ($R \propto l$), cross-sectional area, material, and temperature. Resistance does not change based on applied voltage or current; instead, current changes based on voltage and resistance ($V = IR$).', 'The resistance of a given conductor relies on its length ($R \propto l$), cross-sectional area, material, and temperature. Resistance does not change based on applied voltage or current; instead, current changes based on voltage and resistance ($V = IR$).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
