INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1611fb29-514b-56cc-9301-283b18ccd23a', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 27, '<p>Of the offspring produced by the interbreeding of two organisms with the genotype Tt, the numbers of the genotypes and the phenotypes differing from one another respectively are</p>', '<p>Of the offspring produced by the interbreeding of two organisms with the genotype Tt, the numbers of the genotypes and the phenotypes differing from one another respectively are</p>', NULL, 'A monohybrid cross of Tt x Tt yields offspring with the genotypes TT, Tt, and tt, making 3 distinct genotypes. Due to Mendelian dominance, these express as 2 distinct phenotypes (dominant trait for TT and Tt, and recessive trait for tt).', 'A monohybrid cross of Tt x Tt yields offspring with the genotypes TT, Tt, and tt, making 3 distinct genotypes. Due to Mendelian dominance, these express as 2 distinct phenotypes (dominant trait for TT and Tt, and recessive trait for tt).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
