INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('011a815b-1c53-5181-9cca-416337420bc4', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 29, '<p>Indicated below is the reaction between haematite and carbon monoxide.<br><br>$$Fe_{2}O_{3} + 3CO \longrightarrow 2Fe + 3CO_{2}$$<br><br>What is the mass of Fe that can be produced using one mole of $Fe_{2}O_{3}$? ($Fe=56$)</p>', '<p>Indicated below is the reaction between haematite and carbon monoxide.<br><br>$$Fe_{2}O_{3} + 3CO \longrightarrow 2Fe + 3CO_{2}$$<br><br>What is the mass of Fe that can be produced using one mole of $Fe_{2}O_{3}$? ($Fe=56$)</p>', NULL, 'From the balanced chemical equation, 1 mole of haematite ($Fe_2O_3$) yields 2 moles of Iron ($Fe$).<br>Mass of $Fe$ produced = $2 \times 56 g = 112 g$.', 'From the balanced chemical equation, 1 mole of haematite ($Fe_2O_3$) yields 2 moles of Iron ($Fe$).<br>Mass of $Fe$ produced = $2 \times 56 g = 112 g$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
