INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d1591b00-5c1f-5906-8e78-669b6b1eadf8', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 32, '<p>Consider the following statements.<br><br>A - Catalysts increase the rate of a chemical reaction.<br>B - At the end of the reaction, the chemical composition of the catalyst changes.<br><br>Of the above,</p>', '<p>Consider the following statements.<br><br>A - Catalysts increase the rate of a chemical reaction.<br>B - At the end of the reaction, the chemical composition of the catalyst changes.<br><br>Of the above,</p>', NULL, 'A catalyst is defined as a substance that accelerates a chemical reaction by providing an alternative pathway with a lower activation energy. However, it is not consumed in the reaction and its chemical composition remains entirely unchanged at the end.', 'A catalyst is defined as a substance that accelerates a chemical reaction by providing an alternative pathway with a lower activation energy. However, it is not consumed in the reaction and its chemical composition remains entirely unchanged at the end.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
