INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cffb519b-c290-5edf-82fb-a29b505d0b4a', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 33, '<p>The set ups (1), (2), (3) and (4) shown in the figures were prepared by adding equal volumes of water with equal concentration of carbon dioxide to four identical test tubes. In which set up will there be the lowest carbon dioxide concentration after exposing these four set ups for three hours to identical conditions of light?</p>', '<p>The set ups (1), (2), (3) and (4) shown in the figures were prepared by adding equal volumes of water with equal concentration of carbon dioxide to four identical test tubes. In which set up will there be the lowest carbon dioxide concentration after exposing these four set ups for three hours to identical conditions of light?</p>', NULL, 'Plants consume dissolved carbon dioxide during photosynthesis when exposed to light. Set up 3, which likely represents an aquatic plant in light without an animal respiring and producing additional CO2, will experience the greatest net decrease in CO2 concentration.', 'Plants consume dissolved carbon dioxide during photosynthesis when exposed to light. Set up 3, which likely represents an aquatic plant in light without an animal respiring and producing additional CO2, will experience the greatest net decrease in CO2 concentration.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
