INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8984271e-2b44-5e5c-a489-b34f97c6100a', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 34, '<p>Consider the following statements on polymers.<br><br>A - have a very high relative molecular mass<br>B - small molecules contributing to make them are known as repeating units<br>C - can be classified as artificial and natural based on origin<br><br>Of these, the true statement(s) is/are,</p>', '<p>Consider the following statements on polymers.<br><br>A - have a very high relative molecular mass<br>B - small molecules contributing to make them are known as repeating units<br>C - can be classified as artificial and natural based on origin<br><br>Of these, the true statement(s) is/are,</p>', NULL, 'Small individual molecules that bond to form a polymer are technically called ''monomers''. The distinct structural segments within the final polymer chain itself are the ''repeating units''. Therefore, statement B is chemically inaccurate, leaving A and C as correct.', 'Small individual molecules that bond to form a polymer are technically called ''monomers''. The distinct structural segments within the final polymer chain itself are the ''repeating units''. Therefore, statement B is chemically inaccurate, leaving A and C as correct.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
