INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e9df5c81-519d-5f5b-9d81-aac47ca34599', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 36, '<p>Of the following statements on the velocity-time graphs, which one is false?</p>', '<p>Of the following statements on the velocity-time graphs, which one is false?</p>', NULL, 'The gradient (slope) of a velocity-time graph represents the object''s acceleration. If velocity is actively varying with time, the acceleration is non-zero, meaning the gradient cannot be zero. A zero gradient specifically indicates constant velocity.', 'The gradient (slope) of a velocity-time graph represents the object''s acceleration. If velocity is actively varying with time, the acceleration is non-zero, meaning the gradient cannot be zero. A zero gradient specifically indicates constant velocity.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
