INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('720d8657-4a6c-5cb1-aefb-346f075f1f45', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 37, '<p>What is the pollutant that contributes to the abnormal growth of algae population in oceanic ecosystems?</p>', '<p>What is the pollutant that contributes to the abnormal growth of algae population in oceanic ecosystems?</p>', NULL, 'Excessive amounts of phosphates (often originating from agricultural fertilizer runoff and detergents) cause nutrient enrichment in water bodies. This process, known as eutrophication, triggers rapid and abnormal algal blooms.', 'Excessive amounts of phosphates (often originating from agricultural fertilizer runoff and detergents) cause nutrient enrichment in water bodies. This process, known as eutrophication, triggers rapid and abnormal algal blooms.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
