INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f749f674-15f2-5715-abf9-31dd2ac96102', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 38, '<p>During the discussions held with a few adults living in coastal areas, they stated that at present they witness an increase in the number of outbreaks of storms occurring per year and their severity while coastal erosion occurs largely. Which of the following environmental phenomenon contributes most to this condition?</p>', '<p>During the discussions held with a few adults living in coastal areas, they stated that at present they witness an increase in the number of outbreaks of storms occurring per year and their severity while coastal erosion occurs largely. Which of the following environmental phenomenon contributes most to this condition?</p>', NULL, 'Global warming increases ocean surface temperatures and causes polar ice melt, leading to rising sea levels. These factors directly contribute to heightened storm intensity and severe coastal erosion.', 'Global warming increases ocean surface temperatures and causes polar ice melt, leading to rising sea levels. These factors directly contribute to heightened storm intensity and severe coastal erosion.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correc