INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1e1e9fb0-cc91-53dc-baaa-00b3899f832a', 'c058a930-ead8-5e40-b63d-f6295b287ca0', 39, '<p>The environmental pyramids always indicated in an upright way are,</p>', '<p>The environmental pyramids always indicated in an upright way are,</p>', NULL, 'Due to the laws of thermodynamics, energy is consistently lost as heat at each trophic transfer (the 10% rule). Therefore, an energy pyramid must always be upright. Pyramids of numbers and biomass can sometimes be inverted depending on the ecosystem.', 'Due to the laws of thermodynamics, energy is consistently lost as heat at each trophic transfer (the 10% rule). Therefore, an energy pyramid must always be upright. Pyramids of numbers and biomass can sometimes be inverted depending on the ecosystem.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
